{"file_path": "src/components/admin/flow-builder/FlowCanvas.tsx", "initial_content": "/**
 * Flow Canvas Component
 * 
 * Visual drag-and-drop canvas for building flows with connections between steps.
 * Uses React Flow for the visualization and interaction.
 */

'use client';

import React, { useCallback, useState, useMemo } from 'react';
import { FlowStep, StepType } from '@/lib/models/flow-config';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { 
  Zap, 
  Database, 
  Wrench, 
  FileText, 
  GitBranch, 
  RefreshCw,
  Plus,
  Trash2,
  Settings,
  ChevronRight
} from 'lucide-react';
import { cn } from '@/lib/utils/cn';

interface FlowCanvasProps {
  steps: FlowStep[];
  selectedStepId?: string;
  onStepSelect?: (stepId: string) => void;
  onStepAdd?: (afterStepId?: string) => void;
  onStepDelete?: (stepId: string) => void;
  onStepReorder?: (stepId: string, newIndex: number) => void;
  readOnly?: boolean;
}

interface StepNodeProps {
  step: FlowStep;
  index: number;
  isSelected: boolean;
  isFirst: boolean;
  isLast: boolean;
  onSelect: () => void;
  onDelete: () => void;
  onAddAfter: () => void;
  onMoveUp: () => void;
  onMoveDown: () => void;
  readOnly?: boolean;
}

// Step type to icon mapping
const stepTypeConfig: Record<StepType, { icon: React.ElementType; color: string; bgColor: string }> = {
  GENERATE: { icon: Zap, color: 'text-yellow-600', bgColor: 'bg-yellow-50 dark:bg-yellow-950' },
  RETRIEVE: { icon: Database, color: 'text-blue-600', bgColor: 'bg-blue-50 dark:bg-blue-950' },
  TOOL: { icon: Wrench, color: 'text-purple-600', bgColor: 'bg-purple-50 dark:bg-purple-950' },
  FORMAT: { icon: FileText, color: 'text-green-600', bgColor: 'bg-green-50 dark:bg-green-950' },
  CONDITION: { icon: GitBranch, color: 'text-orange-600', bgColor: 'bg-orange-50 dark:bg-orange-950' },
  LOOP: { icon: RefreshCw, color: 'text-pink-600', bgColor: 'bg-pink-50 dark:bg-pink-950' },
};

function StepNode({
  step,
  index,
  isSelected,
  isFirst,
  isLast,
  onSelect,
  onDelete,
  onAddAfter,
  onMoveUp,
  onMoveDown,
  readOnly = false,
}: StepNodeProps) {
  const config = stepTypeConfig[step.type];
  const Icon = config.icon;

  return (
    <div className="relative group">
      {/* Connection line to previous step */}
      {!isFirst && (
        <div className="absolute left-1/2 -top-6 transform -translate-x-1/2 flex flex-col items-center">
          <ChevronRight className="w-5 h-5 rotate-90 text-muted-foreground" />
        </div>
      )}

      {/* Step Card */}
      <Card
        className={cn(
          'relative cursor-pointer transition-all hover:shadow-md',
          isSelected && 'ring-2 ring-primary shadow-lg',
          config.bgColor
        )}
        onClick={onSelect}
      >
        <CardContent className="p-4">
          <div className="flex items-start gap-3">
            {/* Step Icon */}
            <div className={cn('p-2 rounded-lg bg-white dark:bg-gray-800 shadow-sm')}>
              <Icon className={cn('w-5 h-5', config.color)} />
            </div>

            {/* Step Info */}
            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-2 mb-1">
                <h4 className="font-semibold text-sm truncate">{step.name}</h4>
                <Badge variant="outline" className="text-xs">
                  {step.type}
                </Badge>
              </div>
              {step.description && (
                <p className="text-xs text-muted-foreground line-clamp-2">
                  {step.description}
                </p>
              )}
              <div className="flex items-center gap-1 mt-2">
                <Badge variant="secondary" className="text-xs">
                  Step {index + 1}
                </Badge>
                {step.config.promptName && (
                  <Badge variant="secondary" className="text-xs">
                    {step.config.promptName}
                  </Badge>
                )}
              </div>
            </div>

            {/* Step Actions */}
            {!readOnly && (
              <div className="flex flex-col gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                <Button
                  size="sm"
                  variant="ghost"
                  className="h-6 w-6 p-0"
                  onClick={(e) => {
                    e.stopPropagation();
                    onSelect();
                  }}
                  title="Configure"
                >
                  <Settings className="w-3 h-3" />
                </Button>
                <Button
                  size="sm"
                  variant="ghost"
                  className="h-6 w-6 p-0"
                  onClick={(e) => {
                    e.stopPropagation();
                    onDelete();
                  }}
                  title="Delete"
                >
                  <Trash2 className="w-3 h-3 text-destructive" />
                </Button>
              </div>
            )}
          </div>
        </CardContent>
      </Card>

      {/* Add Step Button (appears between steps) */}
      {!readOnly && (
        <div className="absolute left-1/2 -bottom-8 transform -translate-x-1/2 opacity-0 group-hover:opacity-100 transition-opacity z-10">
          <Button
            size="sm"
            variant="outline"
            className="h-6 w-6 p-0 rounded-full bg-background shadow-md"
            onClick={(e) => {
              e.stopPropagation();
              onAddAfter();
            }}
            title="Add step after"
          >
            <Plus className="w-3 h-3" />
          </Button>
        </div>
      )}
    </div>
  );
}

export function FlowCanvas({
  steps,
  selectedStepId,
  onStepSelect,
  onStepAdd,
  onStepDelete,
  onStepReorder,
  readOnly = false,
}: FlowCanvasProps) {
  const [draggedStepId, setDraggedStepId] = useState<string | null>(null);

  const handleStepDragStart = useCallback((stepId: string) => {
    setDraggedStepId(stepId);
  }, []);

  const handleStepDragEnd = useCallback(() => {
    setDraggedStepId(null);
  }, []);

  const handleStepDrop = useCallback((targetIndex: number) => {
    if (draggedStepId && onStepReorder) {
      onStepReorder(draggedStepId, targetIndex);
    }
    setDraggedStepId(null);
  }, [draggedStepId, onStepReorder]);

  return (
    <div className="relative w-full h-full overflow-auto p-8">
      {steps.length === 0 ? (
        // Empty State
        <div className="flex flex-col items-center justify-center h-full min-h-[400px] text-center">
          <div className="p-6 rounded-full bg-muted/50 mb-4">
            <Zap className="w-12 h-12 text-muted-foreground" />
          </div>
          <h3 className="text-lg font-semibold mb-2">No steps yet</h3>
          <p className="text-sm text-muted-foreground mb-6 max-w-sm">
            Start building your flow by adding steps from the step library.
          </p>
          {!readOnly && onStepAdd && (
            <Button onClick={() => onStepAdd()}>
              <Plus className="w-4 h-4 mr-2" />
              Add First Step
            </Button>
          )}
        </div>
      ) : (
        // Steps List
        <div className="max-w-2xl mx-auto space-y-12">
          {steps.map((step, index) => (
            <StepNode
              key={step.id}
              step={step}
              index={index}
              isSelected={selectedStepId === step.id}
              isFirst={index === 0}
              isLast={index === steps.length - 1}
              onSelect={() => onStepSelect?.(step.id)}
              onDelete={() => onStepDelete?.(step.id)}
              onAddAfter={() => onStepAdd?.(step.id)}
              onMoveUp={() => onStepReorder?.(step.id, index - 1)}
              onMoveDown={() => onStepReorder?.(step.id, index + 1)}
              readOnly={readOnly}
            />
          ))}
        </div>
      )}

      {/* Flow Statistics */}
      {steps.length > 0 && (
        <div className="fixed bottom-4 right-4 bg-background/95 backdrop-blur-sm border rounded-lg shadow-lg p-3">
          <div className="flex items-center gap-4 text-xs">
            <div className="flex items-center gap-1">
              <span className="font-medium">{steps.length}</span>
              <span className="text-muted-foreground">steps</span>
            </div>
            <div className="flex items-center gap-1">
              <span className="font-medium">
                {steps.filter(s => s.type === 'GENERATE').length}
              </span>
              <span className="text-muted-foreground">generate</span>
            </div>
            <div className="flex items-center gap-1">
              <span className="font-medium">
                {steps.filter(s => s.type === 'RETRIEVE').length}
              </span>
              <span className="text-muted-foreground">retrieve</span>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
"}

{"file_path": "src/components/admin/flow-builder/StepEditor.tsx", "initial_content": "/**
 * Step Editor Component
 * 
 * Configuration panel for editing individual flow steps with type-specific options.
 */

'use client';

import React, { useState, useEffect } from 'react';
import { FlowStep, StepType, GenerateStepConfig, RetrieveStepConfig, ToolStepConfig, FormatStepConfig, ConditionStepConfig, LoopStepConfig } from '@/lib/models/flow-config';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Switch } from '@/components/ui/switch';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Badge } from '@/components/ui/badge';
import { Separator } from '@/components/ui/separator';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Save, X, Plus, Trash2, Code, TestTube } from 'lucide-react';
import { cn } from '@/lib/utils/cn';

interface StepEditorProps {
  step: FlowStep;
  onSave: (step: FlowStep) => void;
  onCancel: () => void;
  availablePrompts?: Array<{ name: string; displayName: string }>;
  availableTools?: Array<{ name: string; description: string }>;
}

export function StepEditor({
  step,
  onSave,
  onCancel,
  availablePrompts = [],
  availableTools = [],
}: StepEditorProps) {
  const [editedStep, setEditedStep] = useState<FlowStep>(step);
  const [activeTab, setActiveTab] = useState('basic');

  useEffect(() => {
    setEditedStep(step);
  }, [step]);

  const handleSave = () => {
    onSave(editedStep);
  };

  const updateStepField = <K extends keyof FlowStep>(field: K, value: FlowStep[K]) => {
    setEditedStep({ ...editedStep, [field]: value });
  };

  const updateConfig = (updates: Partial<any>) => {
    setEditedStep({
      ...editedStep,
      config: { ...editedStep.config, ...updates },
    });
  };

  // Render type-specific configuration
  const renderTypeSpecificConfig = () => {
    switch (editedStep.type) {
      case 'GENERATE':
        return <GenerateStepEditor config={editedStep.config as GenerateStepConfig} updateConfig={updateConfig} availablePrompts={availablePrompts} />;
      case 'RETRIEVE':
        return <RetrieveStepEditor config={editedStep.config as RetrieveStepConfig} updateConfig={updateConfig} />;
      case 'TOOL':
        return <ToolStepEditor config={editedStep.config as ToolStepConfig} updateConfig={updateConfig} availableTools={availableTools} />;
      case 'FORMAT':
        return <FormatStepEditor config={editedStep.config as FormatStepConfig} updateConfig={updateConfig} />;
      case 'CONDITION':
        return <ConditionStepEditor config={editedStep.config as ConditionStepConfig} updateConfig={updateConfig} />;
      case 'LOOP':
        return <LoopStepEditor config={editedStep.config as LoopStepConfig} updateConfig={updateConfig} />;
      default:
        return null;
    }
  };

  return (
    <div className="h-full flex flex-col">
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b">
        <div className="flex items-center gap-3">
          <Badge>{editedStep.type}</Badge>
          <h3 className="font-semibold">Configure Step</h3>
        </div>
        <div className="flex items-center gap-2">
          <Button variant="outline" size="sm" onClick={onCancel}>
            <X className="w-4 h-4 mr-2" />
            Cancel
          </Button>
          <Button size="sm" onClick={handleSave}>
            <Save className="w-4 h-4 mr-2" />
            Save
          </Button>
        </div>
      </div>

      {/* Content */}
      <ScrollArea className="flex-1">
        <div className="p-4 space-y-6">
          <Tabs value={activeTab} onValueChange={setActiveTab}>
            <TabsList className="grid w-full grid-cols-3">
              <TabsTrigger value="basic">Basic</TabsTrigger>
              <TabsTrigger value="config">Configuration</TabsTrigger>
              <TabsTrigger value="advanced">Advanced</TabsTrigger>
            </TabsList>

            {/* Basic Tab */}
            <TabsContent value="basic" className="space-y-4">
              <div className="space-y-2">
                <Label htmlFor="step-name">Step Name</Label>
                <Input
                  id="step-name"
                  value={editedStep.name}
                  onChange={(e) => updateStepField('name', e.target.value)}
                  placeholder="e.g., Generate Introduction"
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="step-description">Description</Label>
                <Textarea
                  id="step-description"
                  value={editedStep.description || ''}
                  onChange={(e) => updateStepField('description', e.target.value)}
                  placeholder="Describe what this step does..."
                  rows={3}
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="step-type">Step Type</Label>
                <Select
                  value={editedStep.type}
                  onValueChange={(value: StepType) => updateStepField('type', value)}
                >
                  <SelectTrigger id="step-type">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="GENERATE">Generate - Generate text with LLM</SelectItem>
                    <SelectItem value="RETRIEVE">Retrieve - Fetch context from RAG</SelectItem>
                    <SelectItem value="TOOL">Tool - Execute a tool</SelectItem>
                    <SelectItem value="FORMAT">Format - Format output</SelectItem>
                    <SelectItem value="CONDITION">Condition - Conditional branching</SelectItem>
                    <SelectItem value="LOOP">Loop - Iterative processing</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </TabsContent>

            {/* Configuration Tab */}
            <TabsContent value="config" className="space-y-4">
              {renderTypeSpecificConfig()}
            </TabsContent>

            {/* Advanced Tab */}
            <TabsContent value="advanced" className="space-y-4">
              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <div className="space-y-0.5">
                    <Label>Timeout (seconds)</Label>
                    <p className="text-xs text-muted-foreground">Maximum execution time for this step</p>
                  </div>
                  <Input
                    type="number"
                    className="w-24"
                    value={editedStep.timeout || 30}
                    onChange={(e) => updateStepField('timeout', parseInt(e.target.value))}
                    min={1}
                    max={300}
                  />
                </div>

                <Separator />

                <div className="flex items-center justify-between">
                  <div className="space-y-0.5">
                    <Label>Retries</Label>
                    <p className="text-xs text-muted-foreground">Number of retry attempts on failure</p>
                  </div>
                  <Input
                    type="number"
                    className="w-24"
                    value={editedStep.retries || 0}
                    onChange={(e) => updateStepField('retries', parseInt(e.target.value))}
                    min={0}
                    max={5}
                  />
                </div>

                <Separator />

                <div className="flex items-center justify-between">
                  <div className="space-y-0.5">
                    <Label>Error Handling</Label>
                    <p className="text-xs text-muted-foreground">What to do when this step fails</p>
                  </div>
                  <Select
                    value={editedStep.onError || 'stop'}
                    onValueChange={(value: 'stop' | 'skip' | 'retry') => updateStepField('onError', value)}
                  >
                    <SelectTrigger className="w-32">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="stop">Stop</SelectItem>
                      <SelectItem value="skip">Skip</SelectItem>
                      <SelectItem value="retry">Retry</SelectItem>
                    </SelectContent>
                  </Select>
                </div>

                <Separator />

                <div className="space-y-2">
                  <Label>Condition (Optional)</Label>
                  <p className="text-xs text-muted-foreground mb-2">
                    JavaScript expression to determine if step should run
                  </p>
                  <Textarea
                    value={editedStep.condition || ''}
                    onChange={(e) => updateStepField('condition', e.target.value)}
                    placeholder="e.g., context.userType === 'premium'"
                    rows={3}
                    className="font-mono text-xs"
                  />
                </div>
              </div>
            </TabsContent>
          </Tabs>
        </div>
      </ScrollArea>
    </div>
  );
}

// Type-specific editors
function GenerateStepEditor({
  config,
  updateConfig,
  availablePrompts,
}: {
  config: GenerateStepConfig;
  updateConfig: (updates: Partial<GenerateStepConfig>) => void;
  availablePrompts: Array<{ name: string; displayName: string }>;
}) {
  return (
    <div className="space-y-4">
      <div className="space-y-2">
        <Label>Prompt Template</Label>
        <Select value={config.promptName} onValueChange={(value) => updateConfig({ promptName: value })}>
          <SelectTrigger>
            <SelectValue placeholder="Select a prompt template" />
          </SelectTrigger>
          <SelectContent>
            {availablePrompts.map((prompt) => (
              <SelectItem key={prompt.name} value={prompt.name}>
                {prompt.displayName}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      <div className="space-y-2">
        <Label>Model</Label>
        <Input
          value={config.model || 'gemini-2.0-flash-exp'}
          onChange={(e) => updateConfig({ model: e.target.value })}
          placeholder="Model name"
        />
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div className="space-y-2">
          <Label>Temperature</Label>
          <Input
            type="number"
            value={config.temperature || 0.7}
            onChange={(e) => updateConfig({ temperature: parseFloat(e.target.value) })}
            min={0}
            max={2}
            step={0.1}
          />
        </div>

        <div className="space-y-2">
          <Label>Max Tokens</Label>
          <Input
            type="number"
            value={config.maxTokens || 2048}
            onChange={(e) => updateConfig({ maxTokens: parseInt(e.target.value) })}
            min={1}
            max={8192}
          />
        </div>
      </div>

      <div className="space-y-2">
        <Label>Variables (JSON)</Label>
        <Textarea
          value={JSON.stringify(config.variables || {}, null, 2)}
          onChange={(e) => {
            try {
              const variables = JSON.parse(e.target.value);
              updateConfig({ variables });
            } catch (err) {
              // Invalid JSON, don't update
            }
          }}
          placeholder='{"key": "{{context.value}}"}'
          rows={4}
          className="font-mono text-xs"
        />
      </div>
    </div>
  );
}

function RetrieveStepEditor({
  config,
  updateConfig,
}: {
  config: RetrieveStepConfig;
  updateConfig: (updates: Partial<RetrieveStepConfig>) => void;
}) {
  return (
    <div className="space-y-4">
      <div className="space-y-2">
        <Label>Query Template</Label>
        <Textarea
          value={config.query}
          onChange={(e) => updateConfig({ query: e.target.value })}
          placeholder="{{context.topic}}"
          rows={3}
        />
      </div>

      <div className="space-y-2">
        <Label>Collection</Label>
        <Input
          value={config.collection || 'documents'}
          onChange={(e) => updateConfig({ collection: e.target.value })}
          placeholder="Collection name"
        />
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div className="space-y-2">
          <Label>Top K Results</Label>
          <Input
            type="number"
            value={config.topK || 5}
            onChange={(e) => updateConfig({ topK: parseInt(e.target.value) })}
            min={1}
            max={20}
          />
        </div>

        <div className="space-y-2">
          <Label>Similarity Threshold</Label>
          <Input
            type="number"
            value={config.threshold || 0.7}
            onChange={(e) => updateConfig({ threshold: parseFloat(e.target.value) })}
            min={0}
            max={1}
            step={0.1}
          />
        </div>
      </div>

      <div className="flex items-center justify-between">
        <div className="space-y-0.5">
          <Label>Enable Reranking</Label>
          <p className="text-xs text-muted-foreground">Use reranking for better relevance</p>
        </div>
        <Switch
          checked={config.rerank || false}
          onCheckedChange={(checked) => updateConfig({ rerank: checked })}
        />
      </div>
    </div>
  );
}

function ToolStepEditor({
  config,
  updateConfig,
  availableTools,
}: {
  config: ToolStepConfig;
  updateConfig: (updates: Partial<ToolStepConfig>) => void;
  availableTools: Array<{ name: string; description: string }>;
}) {
  return (
    <div className="space-y-4">
      <div className="space-y-2">
        <Label>Tool Name</Label>
        <Select value={config.toolName} onValueChange={(value) => updateConfig({ toolName: value })}>
          <SelectTrigger>
            <SelectValue placeholder="Select a tool" />
          </SelectTrigger>
          <SelectContent>
            {availableTools.map((tool) => (
              <SelectItem key={tool.name} value={tool.name}>
                {tool.name}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      <div className="space-y-2">
        <Label>Tool Arguments (JSON)</Label>
        <Textarea
          value={JSON.stringify(config.arguments || {}, null, 2)}
          onChange={(e) => {
            try {
              const args = JSON.parse(e.target.value);
              updateConfig({ arguments: args });
            } catch (err) {
              // Invalid JSON
            }
          }}
          placeholder='{"param": "{{context.value}}"}'
          rows={6}
          className="font-mono text-xs"
        />
      </div>
    </div>
  );
}

function FormatStepEditor({
  config,
  updateConfig,
}: {
  config: FormatStepConfig;
  updateConfig: (updates: Partial<FormatStepConfig>) => void;
}) {
  return (
    <div className="space-y-4">
      <div className="space-y-2">
        <Label>Output Format</Label>
        <Select value={config.format} onValueChange={(value) => updateConfig({ format: value as any })}>
          <SelectTrigger>
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="markdown">Markdown</SelectItem>
            <SelectItem value="json">JSON</SelectItem>
            <SelectItem value="text">Plain Text</SelectItem>
            <SelectItem value="html">HTML</SelectItem>
          </SelectContent>
        </Select>
      </div>

      <div className="space-y-2">
        <Label>Template</Label>
        <Textarea
          value={config.template || ''}
          onChange={(e) => updateConfig({ template: e.target.value })}
          placeholder="{{context.result}}"
          rows={6}
          className="font-mono text-xs"
        />
      </div>
    </div>
  );
}

function ConditionStepEditor({
  config,
  updateConfig,
}: {
  config: ConditionStepConfig;
  updateConfig: (updates: Partial<ConditionStepConfig>) => void;
}) {
  return (
    <div className="space-y-4">
      <div className="space-y-2">
        <Label>Condition Expression</Label>
        <Textarea
          value={config.expression}
          onChange={(e) => updateConfig({ expression: e.target.value })}
          placeholder="context.score > 0.8"
          rows={3}
          className="font-mono text-xs"
        />
      </div>

      <div className="space-y-2">
        <Label>True Branch (Next Step ID)</Label>
        <Input
          value={config.trueStepId || ''}
          onChange={(e) => updateConfig({ trueStepId: e.target.value })}
          placeholder="step-id-if-true"
        />
      </div>

      <div className="space-y-2">
        <Label>False Branch (Next Step ID)</Label>
        <Input
          value={config.falseStepId || ''}
          onChange={(e) => updateConfig({ falseStepId: e.target.value })}
          placeholder="step-id-if-false"
        />
      </div>
    </div>
  );
}

function LoopStepEditor({
  config,
  updateConfig,
}: {
  config: LoopStepConfig;
  updateConfig: (updates: Partial<LoopStepConfig>) => void;
}) {
  return (
    <div className="space-y-4">
      <div className="space-y-2">
        <Label>Items Expression</Label>
        <Input
          value={config.items}
          onChange={(e) => updateConfig({ items: e.target.value })}
          placeholder="context.items"
        />
      </div>

      <div className="space-y-2">
        <Label>Item Variable Name</Label>
        <Input
          value={config.itemVar || 'item'}
          onChange={(e) => updateConfig({ itemVar: e.target.value })}
          placeholder="item"
        />
      </div>

      <div className="space-y-2">
        <Label>Loop Body (Step ID)</Label>
        <Input
          value={config.bodyStepId || ''}
          onChange={(e) => updateConfig({ bodyStepId: e.target.value })}
          placeholder="step-id-to-repeat"
        />
      </div>

      <div className="space-y-2">
        <Label>Max Iterations</Label>
        <Input
          type="number"
          value={config.maxIterations || 100}
          onChange={(e) => updateConfig({ maxIterations: parseInt(e.target.value) })}
          min={1}
          max={1000}
        />
      </div>
    </div>
  );
}
