{"file_path": "src/components/admin/prompts/PromptList.tsx", "initial_content": "/**
 * Prompt List Component
 * 
 * List and manage all prompt templates with filtering, sorting, and actions.
 */

'use client';

import React, { useState } from 'react';
import { PromptConfiguration } from '@/lib/models/prompt-config';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { ScrollArea } from '@/components/ui/scroll-area';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Search,
  MoreVertical,
  Edit,
  Copy,
  Trash2,
  Play,
  Archive,
  RotateCcw,
  Filter,
  Plus,
  FileText,
} from 'lucide-react';
import { formatDistanceToNow } from 'date-fns';

interface PromptListProps {
  prompts: PromptConfiguration[];
  onPromptSelect?: (prompt: PromptConfiguration) => void;
  onPromptCreate?: () => void;
  onPromptEdit?: (prompt: PromptConfiguration) => void;
  onPromptDelete?: (promptId: string) => void;
  onPromptDuplicate?: (prompt: PromptConfiguration) => void;
  onPromptTest?: (prompt: PromptConfiguration) => void;
  onPromptArchive?: (promptId: string) => void;
  onPromptRestore?: (promptId: string) => void;
}

export function PromptList({
  prompts,
  onPromptSelect,
  onPromptCreate,
  onPromptEdit,
  onPromptDelete,
  onPromptDuplicate,
  onPromptTest,
  onPromptArchive,
  onPromptRestore,
}: PromptListProps) {
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState<'all' | 'active' | 'draft' | 'archived'>('all');
  const [categoryFilter, setCategoryFilter] = useState<string | 'all'>('all');

  // Filter prompts
  const filteredPrompts = prompts.filter((prompt) => {
    const matchesSearch =
      searchQuery === '' ||
      prompt.displayName.toLowerCase().includes(searchQuery.toLowerCase()) ||
      prompt.description.toLowerCase().includes(searchQuery.toLowerCase()) ||
      prompt.tags.some((tag) => tag.toLowerCase().includes(searchQuery.toLowerCase()));

    const matchesStatus = statusFilter === 'all' || prompt.status === statusFilter;
    const matchesCategory = categoryFilter === 'all' || prompt.category === categoryFilter;

    return matchesSearch && matchesStatus && matchesCategory;
  });

  // Get unique categories
  const categories = Array.from(new Set(prompts.map((p) => p.category)));

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'active':
        return 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-300';
      case 'draft':
        return 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-300';
      case 'archived':
        return 'bg-gray-100 text-gray-800 dark:bg-gray-900 dark:text-gray-300';
      default:
        return 'bg-gray-100 text-gray-800';
    }
  };

  return (
    <div className="h-full flex flex-col">
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b">
        <div>
          <h2 className="text-lg font-semibold">Prompt Templates</h2>
          <p className="text-sm text-muted-foreground">
            {filteredPrompts.length} of {prompts.length} prompts
          </p>
        </div>
        {onPromptCreate && (
          <Button onClick={onPromptCreate}>
            <Plus className="w-4 h-4 mr-2" />
            Create Prompt
          </Button>
        )}
      </div>

      {/* Filters */}
      <div className="flex items-center gap-2 p-4 border-b">
        <div className="relative flex-1">
          <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
          <Input
            placeholder="Search prompts..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="pl-8"
          />
        </div>

        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button variant="outline" size="sm">
              <Filter className="w-4 h-4 mr-2" />
              Status
              {statusFilter !== 'all' && (
                <Badge variant="secondary" className="ml-2">
                  {statusFilter}
                </Badge>
              )}
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent>
            <DropdownMenuItem onClick={() => setStatusFilter('all')}>
              All Statuses
            </DropdownMenuItem>
            <DropdownMenuSeparator />
            <DropdownMenuItem onClick={() => setStatusFilter('active')}>
              Active
            </DropdownMenuItem>
            <DropdownMenuItem onClick={() => setStatusFilter('draft')}>
              Draft
            </DropdownMenuItem>
            <DropdownMenuItem onClick={() => setStatusFilter('archived')}>
              Archived
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>

        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button variant="outline" size="sm">
              <Filter className="w-4 h-4 mr-2" />
              Category
              {categoryFilter !== 'all' && (
                <Badge variant="secondary" className="ml-2">
                  {categoryFilter}
                </Badge>
              )}
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent>
            <DropdownMenuItem onClick={() => setCategoryFilter('all')}>
              All Categories
            </DropdownMenuItem>
            <DropdownMenuSeparator />
            {categories.map((category) => (
              <DropdownMenuItem key={category} onClick={() => setCategoryFilter(category)}>
                {category}
              </DropdownMenuItem>
            ))}
          </DropdownMenuContent>
        </DropdownMenu>
      </div>

      {/* Prompt Table */}
      <ScrollArea className="flex-1">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Name</TableHead>
              <TableHead>Category</TableHead>
              <TableHead>Variables</TableHead>
              <TableHead>Status</TableHead>
              <TableHead>Version</TableHead>
              <TableHead>Updated</TableHead>
              <TableHead className="w-[50px]"></TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {filteredPrompts.map((prompt) => (
              <TableRow
                key={prompt.id}
                className="cursor-pointer hover:bg-muted/50"
                onClick={() => onPromptSelect?.(prompt)}
              >
                <TableCell>
                  <div>
                    <div className="flex items-center gap-2">
                      <FileText className="w-4 h-4 text-muted-foreground" />
                      <span className="font-medium">{prompt.displayName}</span>
                    </div>
                    <div className="text-xs text-muted-foreground line-clamp-1 mt-1">
                      {prompt.description}
                    </div>
                    {prompt.tags.length > 0 && (
                      <div className="flex gap-1 mt-1">
                        {prompt.tags.slice(0, 3).map((tag) => (
                          <Badge key={tag} variant="secondary" className="text-xs">
                            {tag}
                          </Badge>
                        ))}
                      </div>
                    )}
                  </div>
                </TableCell>
                <TableCell>
                  <Badge variant="outline">{prompt.category}</Badge>
                </TableCell>
                <TableCell>{prompt.variables.length}</TableCell>
                <TableCell>
                  <Badge className={getStatusColor(prompt.status)}>{prompt.status}</Badge>
                </TableCell>
                <TableCell className="text-sm">{prompt.version}</TableCell>
                <TableCell className="text-sm text-muted-foreground">
                  {prompt.updatedAt
                    ? formatDistanceToNow(new Date(prompt.updatedAt.seconds * 1000), {
                        addSuffix: true,
                      })
                    : 'Never'}
                </TableCell>
                <TableCell>
                  <DropdownMenu>
                    <DropdownMenuTrigger asChild>
                      <Button
                        variant="ghost"
                        size="sm"
                        className="h-8 w-8 p-0"
                        onClick={(e) => e.stopPropagation()}
                      >
                        <MoreVertical className="w-4 h-4" />
                      </Button>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="end">
                      {onPromptEdit && (
                        <DropdownMenuItem onClick={() => onPromptEdit(prompt)}>
                          <Edit className="w-4 h-4 mr-2" />
                          Edit
                        </DropdownMenuItem>
                      )}
                      {onPromptTest && (
                        <DropdownMenuItem onClick={() => onPromptTest(prompt)}>
                          <Play className="w-4 h-4 mr-2" />
                          Test
                        </DropdownMenuItem>
                      )}
                      {onPromptDuplicate && (
                        <DropdownMenuItem onClick={() => onPromptDuplicate(prompt)}>
                          <Copy className="w-4 h-4 mr-2" />
                          Duplicate
                        </DropdownMenuItem>
                      )}
                      <DropdownMenuSeparator />
                      {prompt.status === 'archived' ? (
                        onPromptRestore && (
                          <DropdownMenuItem onClick={() => onPromptRestore(prompt.id!)}>
                            <RotateCcw className="w-4 h-4 mr-2" />
                            Restore
                          </DropdownMenuItem>
                        )
                      ) : (
                        onPromptArchive && (
                          <DropdownMenuItem onClick={() => onPromptArchive(prompt.id!)}>
                            <Archive className="w-4 h-4 mr-2" />
                            Archive
                          </DropdownMenuItem>
                        )
                      )}
                      {onPromptDelete && (
                        <DropdownMenuItem
                          onClick={() => onPromptDelete(prompt.id!)}
                          className="text-destructive"
                        >
                          <Trash2 className="w-4 h-4 mr-2" />
                          Delete
                        </DropdownMenuItem>
                      )}
                    </DropdownMenuContent>
                  </DropdownMenu>
                </TableCell>
              </TableRow>
            ))}

            {filteredPrompts.length === 0 && (
              <TableRow>
                <TableCell colSpan={7} className="text-center py-8">
                  <p className="text-sm text-muted-foreground">No prompts found</p>
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </ScrollArea>
    </div>
  );
}
"}

{"file_path": "src/components/admin/prompts/VariableEditor.tsx", "initial_content": "/**
 * Variable Editor Component
 * 
 * Editor for defining and managing prompt variables and their schemas.
 */

'use client';

import React, { useState } from 'react';
import { PromptVariable } from '@/lib/models/prompt-config';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Switch } from '@/components/ui/switch';
import { Badge } from '@/components/ui/badge';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Separator } from '@/components/ui/separator';
import { Plus, Trash2, Code, ChevronDown, ChevronRight } from 'lucide-react';
import { cn } from '@/lib/utils/cn';

interface VariableEditorProps {
  variables: PromptVariable[];
  onChange: (variables: PromptVariable[]) => void;
  onInsertVariable?: (variableName: string) => void;
}

export function VariableEditor({ variables, onChange, onInsertVariable }: VariableEditorProps) {
  const [selectedIndex, setSelectedIndex] = useState<number | null>(null);
  const [expandedIndices, setExpandedIndices] = useState<Set<number>>(new Set());

  const handleAddVariable = () => {
    const newVariable: PromptVariable = {
      name: `variable${variables.length + 1}`,
      type: 'string',
      description: '',
      required: false,
    };
    onChange([...variables, newVariable]);
    setSelectedIndex(variables.length);
    setExpandedIndices(new Set([...expandedIndices, variables.length]));
  };

  const handleUpdateVariable = (index: number, updates: Partial<PromptVariable>) => {
    const updatedVariables = [...variables];
    updatedVariables[index] = { ...updatedVariables[index], ...updates };
    onChange(updatedVariables);
  };

  const handleDeleteVariable = (index: number) => {
    const updatedVariables = variables.filter((_, i) => i !== index);
    onChange(updatedVariables);
    if (selectedIndex === index) {
      setSelectedIndex(null);
    }
  };

  const toggleExpanded = (index: number) => {
    const newExpanded = new Set(expandedIndices);
    if (newExpanded.has(index)) {
      newExpanded.delete(index);
    } else {
      newExpanded.add(index);
    }
    setExpandedIndices(newExpanded);
  };

  const getTypeColor = (type: string) => {
    switch (type) {
      case 'string':
        return 'text-blue-600 bg-blue-50 dark:bg-blue-950';
      case 'number':
        return 'text-green-600 bg-green-50 dark:bg-green-950';
      case 'boolean':
        return 'text-purple-600 bg-purple-50 dark:bg-purple-950';
      case 'array':
        return 'text-orange-600 bg-orange-50 dark:bg-orange-950';
      case 'object':
        return 'text-pink-600 bg-pink-50 dark:bg-pink-950';
      default:
        return 'text-gray-600 bg-gray-50 dark:bg-gray-950';
    }
  };

  return (
    <div className="h-full flex flex-col">
      <CardHeader className="pb-3">
        <div className="flex items-center justify-between">
          <div>
            <CardTitle className="text-base">Variables</CardTitle>
            <CardDescription className="text-xs">
              Define variables used in your prompt template
            </CardDescription>
          </div>
          <Button size="sm" variant="outline" onClick={handleAddVariable}>
            <Plus className="w-4 h-4 mr-2" />
            Add Variable
          </Button>
        </div>
      </CardHeader>

      <CardContent className="flex-1 flex flex-col overflow-hidden p-4 pt-0">
        {variables.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full text-center py-8">
            <Code className="w-12 h-12 text-muted-foreground mb-4" />
            <h3 className="font-semibold mb-2">No variables defined</h3>
            <p className="text-sm text-muted-foreground mb-4 max-w-sm">
              Variables allow you to pass dynamic data into your prompt templates.
            </p>
            <Button size="sm" onClick={handleAddVariable}>
              <Plus className="w-4 h-4 mr-2" />
              Add First Variable
            </Button>
          </div>
        ) : (
          <ScrollArea className="flex-1 pr-4">
            <div className="space-y-2">
              {variables.map((variable, index) => {
                const isExpanded = expandedIndices.has(index);
                const isSelected = selectedIndex === index;

                return (
                  <Card
                    key={index}
                    className={cn(
                      'transition-all cursor-pointer',
                      isSelected && 'ring-2 ring-primary'
                    )}
                    onClick={() => setSelectedIndex(index)}
                  >
                    <CardContent className="p-3">
                      {/* Variable Header */}
                      <div className="flex items-center justify-between mb-2">
                        <div className="flex items-center gap-2 flex-1 min-w-0">
                          <Button
                            variant="ghost"
                            size="sm"
                            className="h-6 w-6 p-0"
                            onClick={(e) => {
                              e.stopPropagation();
                              toggleExpanded(index);
                            }}
                          >
                            {isExpanded ? (
                              <ChevronDown className="w-4 h-4" />
                            ) : (
                              <ChevronRight className="w-4 h-4" />
                            )}
                          </Button>
                          <code className="text-sm font-mono font-semibold truncate">
                            {'{{'}{variable.name}{'}}'}
                          </code>
                          <Badge variant="outline" className={cn('text-xs', getTypeColor(variable.type))}>
                            {variable.type}
                          </Badge>
                          {variable.required && (
                            <Badge variant="destructive" className="text-xs">
                              Required
                            </Badge>
                          )}
                        </div>
                        <div className="flex items-center gap-1">
                          {onInsertVariable && (
                            <Button
                              variant="ghost"
                              size="sm"
                              className="h-6 px-2"
                              onClick={(e) => {
                                e.stopPropagation();
                                onInsertVariable(variable.name);
                              }}
                            >
                              <Code className="w-3 h-3" />
                            </Button>
                          )}
                          <Button
                            variant="ghost"
                            size="sm"
                            className="h-6 px-2 text-destructive"
                            onClick={(e) => {
                              e.stopPropagation();
                              handleDeleteVariable(index);
                            }}
                          >
                            <Trash2 className="w-3 h-3" />
                          </Button>
                        </div>
                      </div>

                      {/* Variable Details (Collapsed) */}
                      {!isExpanded && variable.description && (
                        <p className="text-xs text-muted-foreground line-clamp-1 ml-8">
                          {variable.description}
                        </p>
                      )}

                      {/* Variable Editor (Expanded) */}
                      {isExpanded && (
                        <div className="space-y-3 mt-3 ml-8">
                          <Separator />

                          <div className="space-y-2">
                            <Label htmlFor={`var-name-${index}`} className="text-xs">
                              Variable Name
                            </Label>
                            <Input
                              id={`var-name-${index}`}
                              value={variable.name}
                              onChange={(e) => handleUpdateVariable(index, { name: e.target.value })}
                              placeholder="variableName"
                              className="h-8 text-sm font-mono"
                              onClick={(e) => e.stopPropagation()}
                            />
                          </div>

                          <div className="space-y-2">
                            <Label htmlFor={`var-type-${index}`} className="text-xs">
                              Type
                            </Label>
                            <Select
                              value={variable.type}
                              onValueChange={(value: any) => handleUpdateVariable(index, { type: value })}
                            >
                              <SelectTrigger id={`var-type-${index}`} className="h-8 text-sm">
                                <SelectValue />
                              </SelectTrigger>
                              <SelectContent>
                                <SelectItem value="string">String</SelectItem>
                                <SelectItem value="number">Number</SelectItem>
                                <SelectItem value="boolean">Boolean</SelectItem>
                                <SelectItem value="array">Array</SelectItem>
                                <SelectItem value="object">Object</SelectItem>
                              </SelectContent>
                            </Select>
                          </div>

                          <div className="space-y-2">
                            <Label htmlFor={`var-desc-${index}`} className="text-xs">
                              Description
                            </Label>
                            <Textarea
                              id={`var-desc-${index}`}
                              value={variable.description || ''}
                              onChange={(e) =>
                                handleUpdateVariable(index, { description: e.target.value })
                              }
                              placeholder="Describe this variable..."
                              rows={2}
                              className="text-sm"
                              onClick={(e) => e.stopPropagation()}
                            />
                          </div>

                          <div className="flex items-center justify-between">
                            <div className="space-y-0.5">
                              <Label htmlFor={`var-required-${index}`} className="text-xs">
                                Required
                              </Label>
                              <p className="text-xs text-muted-foreground">
                                This variable must be provided
                              </p>
                            </div>
                            <Switch
                              id={`var-required-${index}`}
                              checked={variable.required}
                              onCheckedChange={(checked) =>
                                handleUpdateVariable(index, { required: checked })
                              }
                              onClick={(e) => e.stopPropagation()}
                            />
                          </div>

                          {variable.defaultValue !== undefined && (
                            <div className="space-y-2">
                              <Label htmlFor={`var-default-${index}`} className="text-xs">
                                Default Value
                              </Label>
                              <Input
                                id={`var-default-${index}`}
                                value={String(variable.defaultValue)}
                                onChange={(e) =>
                                  handleUpdateVariable(index, { defaultValue: e.target.value })
                                }
                                placeholder="Default value..."
                                className="h-8 text-sm"
                                onClick={(e) => e.stopPropagation()}
                              />
                            </div>
                          )}
                        </div>
                      )}
                    </CardContent>
                  </Card>
                );
              })}
            </div>
          </ScrollArea>
        )}
      </CardContent>
    </div>
  );
}
"}

{"file_path": "src/components/admin/flow-builder/FlowTester.tsx", "initial_content": "/**
 * Flow Tester Component
 * 
 * Interactive testing interface for flows with input configuration and result display.
 */

'use client';

import React, { useState } from 'react';
import { FlowConfiguration } from '@/lib/models/flow-config';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { Play, CheckCircle, XCircle, Clock, Loader2, Copy } from 'lucide-react';
import { cn } from '@/lib/utils/cn';

interface FlowTesterProps {
  flow: FlowConfiguration;
  onTest?: (flowId: string, input: Record<string, any>) => Promise<any>;
}

interface TestResult {
  status: 'success' | 'error' | 'running';
  output?: any;
  error?: string;
  duration?: number;
  steps?: Array<{
    stepId: string;
    stepName: string;
    status: 'success' | 'error' | 'skipped';
    output?: any;
    error?: string;
    duration?: number;
  }>;
}

export function FlowTester({ flow, onTest }: FlowTesterProps) {
  const [input, setInput] = useState('{}');
  const [testResult, setTestResult] = useState<TestResult | null>(null);
  const [isRunning, setIsRunning] = useState(false);
  const [activeTab, setActiveTab] = useState('input');

  const handleTest = async () => {
    if (!onTest) return;

    try {
      setIsRunning(true);
      setTestResult({ status: 'running' });
      setActiveTab('result');

      const startTime = Date.now();
      const parsedInput = JSON.parse(input);

      const result = await onTest(flow.id!, parsedInput);
      const duration = Date.now() - startTime;

      setTestResult({
        status: 'success',
        output: result,
        duration,
      });
    } catch (error) {
      setTestResult({
        status: 'error',
        error: error instanceof Error ? error.message : 'Unknown error',
      });
    } finally {
      setIsRunning(false);
    }
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
  };

  return (
    <div className="h-full flex flex-col">
      {/* Header */}
      <div className="p-4 border-b">
        <div className="flex items-center justify-between">
          <div>
            <h3 className="font-semibold">Test Flow</h3>
            <p className="text-sm text-muted-foreground">{flow.displayName}</p>
          </div>
          <Button onClick={handleTest} disabled={isRunning || !onTest}>
            {isRunning ? (
              <Loader2 className="w-4 h-4 mr-2 animate-spin" />
            ) : (
              <Play className="w-4 h-4 mr-2" />
            )}
            Run Test
          </Button>
        </div>
      </div>

      {/* Content */}
      <div className="flex-1 overflow-hidden">
        <Tabs value={activeTab} onValueChange={setActiveTab} className="h-full flex flex-col">
          <TabsList className="mx-4 mt-4">
            <TabsTrigger value="input">Input</TabsTrigger>
            <TabsTrigger value="result">Result</TabsTrigger>
            <TabsTrigger value="steps">Steps</TabsTrigger>
          </TabsList>

          {/* Input Tab */}
          <TabsContent value="input" className="flex-1 px-4 pb-4 overflow-auto">
            <Card>
              <CardHeader>
                <CardTitle className="text-base">Test Input</CardTitle>
                <CardDescription>
                  Provide input data as JSON for testing the flow
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="space-y-2">
                  <Label>Input Data (JSON)</Label>
                  <Textarea
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    placeholder='{"key": "value"}'
                    rows={12}
                    className="font-mono text-sm"
                  />
                </div>

                {/* Flow Info */}
                <div className="space-y-2">
                  <h4 className="text-sm font-medium">Flow Information</h4>
                  <div className="grid grid-cols-2 gap-2 text-sm">
                    <div className="flex justify-between">
                      <span className="text-muted-foreground">Steps:</span>
                      <span className="font-medium">{flow.steps.length}</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-muted-foreground">Status:</span>
                      <Badge variant="outline">{flow.status}</Badge>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-muted-foreground">Category:</span>
                      <span className="font-medium">{flow.category}</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-muted-foreground">Version:</span>
                      <span className="font-medium">{flow.version}</span>
                    </div>
                  </div>
                </div>
              </CardContent>
            </Card>
          </TabsContent>

          {/* Result Tab */}
          <TabsContent value="result" className="flex-1 px-4 pb-4 overflow-auto">
            <Card>
              <CardHeader>
                <div className="flex items-center justify-between">
                  <CardTitle className="text-base">Test Result</CardTitle>
                  {testResult && (
                    <div className="flex items-center gap-2">
                      {testResult.status === 'running' && (
                        <Badge variant="secondary">
                          <Loader2 className="w-3 h-3 mr-1 animate-spin" />
                          Running
                        </Badge>
                      )}
                      {testResult.status === 'success' && (
                        <Badge variant="default" className="bg-green-500">
                          <CheckCircle className="w-3 h-3 mr-1" />
                          Success
                        </Badge>
                      )}
                      {testResult.status === 'error' && (
                        <Badge variant="destructive">
                          <XCircle className="w-3 h-3 mr-1" />
                          Error
                        </Badge>
                      )}
                      {testResult.duration && (
                        <Badge variant="outline">
                          <Clock className="w-3 h-3 mr-1" />
                          {testResult.duration}ms
                        </Badge>
                      )}
                    </div>
                  )}
                </div>
              </CardHeader>
              <CardContent>
                {!testResult ? (
                  <div className="text-center py-8 text-muted-foreground">
                    <Play className="w-12 h-12 mx-auto mb-4 opacity-50" />
                    <p>Run a test to see results</p>
                  </div>
                ) : testResult.status === 'running' ? (
                  <div className="text-center py-8">
                    <Loader2 className="w-12 h-12 mx-auto mb-4 animate-spin text-primary" />
                    <p className="text-sm text-muted-foreground">Executing flow...</p>
                  </div>
                ) : testResult.status === 'error' ? (
                  <Alert variant="destructive">
                    <XCircle className="w-4 h-4" />
                    <AlertDescription>{testResult.error}</AlertDescription>
                  </Alert>
                ) : (
                  <div className="space-y-4">
                    <div className="flex items-center justify-between">
                      <Label>Output</Label>
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => copyToClipboard(JSON.stringify(testResult.output, null, 2))}
                      >
                        <Copy className="w-4 h-4 mr-2" />
                        Copy
                      </Button>
                    </div>
                    <ScrollArea className="h-[400px]">
                      <pre className="p-4 bg-muted rounded-lg text-xs font-mono overflow-x-auto">
                        {JSON.stringify(testResult.output, null, 2)}
                      </pre>
                    </ScrollArea>
                  </div>
                )}
              </CardContent>
            </Card>
          </TabsContent>

          {/* Steps Tab */}
          <TabsContent value="steps" className="flex-1 px-4 pb-4 overflow-auto">
            <Card>
              <CardHeader>
                <CardTitle className="text-base">Step Execution</CardTitle>
                <CardDescription>
                  Detailed execution information for each step
                </CardDescription>
              </CardHeader>
              <CardContent>
                {!testResult?.steps ? (
                  <div className="text-center py-8 text-muted-foreground">
                    <p>No step execution data available</p>
                  </div>
                ) : (
                  <div className="space-y-3">
                    {testResult.steps.map((step, index) => (
                      <Card key={step.stepId}>
                        <CardContent className="p-4">
                          <div className="flex items-start justify-between mb-2">
                            <div className="flex items-center gap-2">
                              <Badge variant="outline">{index + 1}</Badge>
                              <span className="font-medium">{step.stepName}</span>
                            </div>
                            <div className="flex items-center gap-2">
                              {step.status === 'success' && (
                                <CheckCircle className="w-4 h-4 text-green-500" />
                              )}
                              {step.status === 'error' && (
                                <XCircle className="w-4 h-4 text-destructive" />
                              )}
                              {step.status === 'skipped' && (
                                <Badge variant="secondary">Skipped</Badge>
                              )}
                              {step.duration && (
                                <Badge variant="outline" className="text-xs">
                                  {step.duration}ms
                                </Badge>
                              )}
                            </div>
                          </div>
                          {step.error && (
                            <Alert variant="destructive" className="mt-2">
                              <AlertDescription className="text-xs">{step.error}</AlertDescription>
                            </Alert>
                          )}
                          {step.output && (
                            <details className="mt-2">
                              <summary className="text-xs text-muted-foreground cursor-pointer hover:text-foreground">
                                View output
                              </summary>
                              <pre className="mt-2 p-2 bg-muted rounded text-xs font-mono overflow-x-auto">
                                {JSON.stringify(step.output, null, 2)}
                              </pre>
                            </details>
                          )}
                        </CardContent>
                      </Card>
                    ))}
                  </div>
                )}
              </CardContent>
            </Card>
          </TabsContent>
        </Tabs>
      </div>
    </div>
  );
}
"}

{"file_path": "src/components/admin/tools/ToolRegistry.tsx", "initial_content": "/**
 * Tool Registry Component
 * 
 * Manage and view registered tools available for use in flows.
 */

'use client';

import React, { useState } from 'react';
import { ToolConfiguration } from '@/lib/models/tool-config';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import {
  Search,
  Wrench,
  Code,
  ExternalLink,
  Settings,
  Plus,
  Filter,
} from 'lucide-react';
import { cn } from '@/lib/utils/cn';

interface ToolRegistryProps {
  tools: ToolConfiguration[];
  onToolSelect?: (tool: ToolConfiguration) => void;
  onToolAdd?: () => void;
}

export function ToolRegistry({ tools, onToolSelect, onToolAdd }: ToolRegistryProps) {
  const [searchQuery, setSearchQuery] = useState('');
  const [typeFilter, setTypeFilter] = useState<string | 'all'>('all');
  const [selectedTool, setSelectedTool] = useState<ToolConfiguration | null>(null);

  // Filter tools
  const filteredTools = tools.filter((tool) => {
    const matchesSearch =
      searchQuery === '' ||
      tool.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      tool.description.toLowerCase().includes(searchQuery.toLowerCase());

    const matchesType = typeFilter === 'all' || tool.type === typeFilter;

    return matchesSearch && matchesType;
  });

  // Group by type
  const toolsByType = filteredTools.reduce((acc, tool) => {
    if (!acc[tool.type]) {
      acc[tool.type] = [];
    }
    acc[tool.type].push(tool);
    return acc;
  }, {} as Record<string, ToolConfiguration[]>);

  const getTypeIcon = (type: string) => {
    switch (type) {
      case 'built-in':
        return Wrench;
      case 'custom':
        return Code;
      case 'external':
        return ExternalLink;
      default:
        return Settings;
    }
  };

  const getTypeColor = (type: string) => {
    switch (type) {
      case 'built-in':
        return 'bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-300';
      case 'custom':
        return 'bg-purple-100 text-purple-800 dark:bg-purple-900 dark:text-purple-300';
      case 'external':
        return 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-300';
      default:
        return 'bg-gray-100 text-gray-800 dark:bg-gray-900 dark:text-gray-300';
    }
  };

  return (
    <div className="h-full flex">
      {/* Tool List */}
      <div className="w-96 border-r flex flex-col">
        <div className="p-4 border-b space-y-4">
          <div className="flex items-center justify-between">
            <h3 className="font-semibold">Tools Registry</h3>
            {onToolAdd && (
              <Button size="sm" variant="outline" onClick={onToolAdd}>
                <Plus className="w-4 h-4 mr-2" />
                Add Tool
              </Button>
            )}
          </div>

          <div className="relative">
            <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
            <Input
              placeholder="Search tools..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="pl-8"
            />
          </div>

          <div className="flex gap-2">
            <Button
              variant={typeFilter === 'all' ? 'default' : 'outline'}
              size="sm"
              onClick={() => setTypeFilter('all')}
            >
              All ({tools.length})
            </Button>
            <Button
              variant={typeFilter === 'built-in' ? 'default' : 'outline'}
              size="sm"
              onClick={() => setTypeFilter('built-in')}
            >
              Built-in
            </Button>
            <Button
              variant={typeFilter === 'custom' ? 'default' : 'outline'}
              size="sm"
              onClick={() => setTypeFilter('custom')}
            >
              Custom
            </Button>
            <Button
              variant={typeFilter === 'external' ? 'default' : 'outline'}
              size="sm"
              onClick={() => setTypeFilter('external')}
            >
              External
            </Button>
          </div>
        </div>

        <ScrollArea className="flex-1">
          <div className="p-4 space-y-4">
            {Object.entries(toolsByType).map(([type, typeTools]) => (
              <div key={type}>
                <h4 className="text-sm font-medium text-muted-foreground mb-2 flex items-center gap-2">
                  {React.createElement(getTypeIcon(type), { className: 'w-4 h-4' })}
                  {type.charAt(0).toUpperCase() + type.slice(1)} ({typeTools.length})
                </h4>
                <div className="space-y-2">
                  {typeTools.map((tool) => (
                    <Card
                      key={tool.name}
                      className={cn(
                        'cursor-pointer hover:border-primary transition-colors',
                        selectedTool?.name === tool.name && 'border-primary bg-muted/50'
                      )}
                      onClick={() => {
                        setSelectedTool(tool);
                        onToolSelect?.(tool);
                      }}
                    >
                      <CardContent className="p-3">
                        <div className="flex items-start justify-between mb-1">
                          <h5 className="font-medium text-sm">{tool.name}</h5>
                          <Badge className={cn('text-xs', getTypeColor(tool.type))}>
                            {tool.type}
                          </Badge>
                        </div>
                        <p className="text-xs text-muted-foreground line-clamp-2">
                          {tool.description}
                        </p>
                      </CardContent>
                    </Card>
                  ))}
                </div>
              </div>
            ))}

            {filteredTools.length === 0 && (
              <div className="text-center py-8 text-muted-foreground">
                <Wrench className="w-12 h-12 mx-auto mb-4 opacity-50" />
                <p>No tools found</p>
              </div>
            )}
          </div>
        </ScrollArea>
      </div>

      {/* Tool Details */}
      <div className="flex-1 overflow-auto">
        {selectedTool ? (
          <div className="p-6 max-w-3xl">
            <Card>
              <CardHeader>
                <div className="flex items-start justify-between">
                  <div>
                    <CardTitle>{selectedTool.name}</CardTitle>
                    <CardDescription>{selectedTool.description}</CardDescription>
                  </div>
                  <Badge className={getTypeColor(selectedTool.type)}>
                    {selectedTool.type}
                  </Badge>
                </div>
              </CardHeader>
              <CardContent className="space-y-6">
                {/* Configuration */}
                <div>
                  <h4 className="font-medium mb-3">Configuration</h4>
                  <div className="grid gap-2 text-sm">
                    <div className="flex justify-between py-2 border-b">
                      <span className="text-muted-foreground">Tool Name:</span>
                      <code className="font-mono text-xs bg-muted px-2 py-1 rounded">
                        {selectedTool.name}
                      </code>
                    </div>
                    <div className="flex justify-between py-2 border-b">
                      <span className="text-muted-foreground">Type:</span>
                      <span className="font-medium">{selectedTool.type}</span>
                    </div>
                    {selectedTool.timeout && (
                      <div className="flex justify-between py-2 border-b">
                        <span className="text-muted-foreground">Timeout:</span>
                        <span className="font-medium">{selectedTool.timeout}ms</span>
                      </div>
                    )}
                  </div>
                </div>

                {/* Input Schema */}
                {selectedTool.inputSchema && (
                  <div>
                    <h4 className="font-medium mb-3">Input Schema</h4>
                    <pre className="p-4 bg-muted rounded-lg text-xs font-mono overflow-x-auto">
                      {JSON.stringify(selectedTool.inputSchema, null, 2)}
                    </pre>
                  </div>
                )}

                {/* Output Schema */}
                {selectedTool.outputSchema && (
                  <div>
                    <h4 className="font-medium mb-3">Output Schema</h4>
                    <pre className="p-4 bg-muted rounded-lg text-xs font-mono overflow-x-auto">
                      {JSON.stringify(selectedTool.outputSchema, null, 2)}
                    </pre>
                  </div>
                )}

                {/* Handler Info */}
                {selectedTool.handler && (
                  <div>
                    <h4 className="font-medium mb-3">Handler</h4>
                    <code className="block p-4 bg-muted rounded-lg text-xs font-mono overflow-x-auto">
                      {selectedTool.handler}
                    </code>
                  </div>
                )}
              </CardContent>
            </Card>
          </div>
        ) : (
          <div className="flex items-center justify-center h-full text-muted-foreground">
            <div className="text-center">
              <Wrench className="w-16 h-16 mx-auto mb-4 opacity-50" />
              <p>Select a tool to view details</p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
"}

{"file_path": "src/app/admin/flows/page.tsx", "initial_content": "/**
 * Admin Flows Management Page
 * 
 * Page for managing dynamic flows with create, edit, delete operations.
 */

'use client';

import React, { useState } from 'react';
import { FlowConfiguration } from '@/lib/models/flow-config';
import { FlowList } from '@/components/admin/flow-builder/FlowList';
import { FlowBuilderInterface } from '@/components/admin/flow-builder/FlowBuilderInterface';
import { FlowTester } from '@/components/admin/flow-builder/FlowTester';
import { Button } from '@/components/ui/button';
import { Sheet, SheetContent } from '@/components/ui/sheet';
import { useToast } from '@/hooks/util/use-toast';
import { ArrowLeft } from 'lucide-react';

export default function AdminFlowsPage() {
  const [flows, setFlows] = useState<FlowConfiguration[]>([]);
  const [selectedFlow, setSelectedFlow] = useState<FlowConfiguration | null>(null);
  const [mode, setMode] = useState<'list' | 'edit' | 'test'>('list');
  const [isLoading, setIsLoading] = useState(false);
  const { toast } = useToast();

  // Fetch flows on mount
  React.useEffect(() => {
    fetchFlows();
  }, []);

  const fetchFlows = async () => {
    try {
      setIsLoading(true);
      const response = await fetch('/api/admin/flows');
      if (!response.ok) throw new Error('Failed to fetch flows');
      const data = await response.json();
      setFlows(data.flows || []);
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to load flows',
        variant: 'destructive',
      });
    } finally {
      setIsLoading(false);
    }
  };

  const handleCreateFlow = () => {
    setSelectedFlow(null);
    setMode('edit');
  };

  const handleEditFlow = (flow: FlowConfiguration) => {
    setSelectedFlow(flow);
    setMode('edit');
  };

  const handleTestFlow = (flow: FlowConfiguration) => {
    setSelectedFlow(flow);
    setMode('test');
  };

  const handleSaveFlow = async (flowData: Partial<FlowConfiguration>) => {
    try {
      const url = selectedFlow?.id
        ? `/api/admin/flows/${selectedFlow.id}`
        : '/api/admin/flows';

      const method = selectedFlow?.id ? 'PUT' : 'POST';

      const response = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(flowData),
      });

      if (!response.ok) throw new Error('Failed to save flow');

      toast({
        title: 'Success',
        description: `Flow ${selectedFlow?.id ? 'updated' : 'created'} successfully`,
      });

      await fetchFlows();
      setMode('list');
      setSelectedFlow(null);
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to save flow',
        variant: 'destructive',
      });
    }
  };

  const handleDeleteFlow = async (flowId: string) => {
    if (!confirm('Are you sure you want to delete this flow?')) return;

    try {
      const response = await fetch(`/api/admin/flows/${flowId}`, {
        method: 'DELETE',
      });

      if (!response.ok) throw new Error('Failed to delete flow');

      toast({
        title: 'Success',
        description: 'Flow deleted successfully',
      });

      await fetchFlows();
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to delete flow',
        variant: 'destructive',
      });
    }
  };

  const handleDuplicateFlow = async (flow: FlowConfiguration) => {
    const duplicate = {
      ...flow,
      name: `${flow.name}-copy`,
      displayName: `${flow.displayName} (Copy)`,
      status: 'draft' as const,
    };
    delete duplicate.id;

    try {
      const response = await fetch('/api/admin/flows', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(duplicate),
      });

      if (!response.ok) throw new Error('Failed to duplicate flow');

      toast({
        title: 'Success',
        description: 'Flow duplicated successfully',
      });

      await fetchFlows();
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to duplicate flow',
        variant: 'destructive',
      });
    }
  };

  const handleRunTest = async (flowId: string, input: Record<string, any>) => {
    const response = await fetch('/api/flows/test', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ flowId, input }),
    });

    if (!response.ok) throw new Error('Test execution failed');

    return await response.json();
  };

  if (mode === 'edit') {
    return (
      <div className="h-screen flex flex-col">
        <div className="border-b p-4">
          <Button variant="ghost" size="sm" onClick={() => setMode('list')}>
            <ArrowLeft className="w-4 h-4 mr-2" />
            Back to Flows
          </Button>
        </div>
        <div className="flex-1 overflow-hidden">
          <FlowBuilderInterface
            initialFlow={selectedFlow || undefined}
            onSave={handleSaveFlow}
            onTest={(flow) => {
              setSelectedFlow(flow as FlowConfiguration);
              setMode('test');
            }}
          />
        </div>
      </div>
    );
  }

  if (mode === 'test' && selectedFlow) {
    return (
      <div className="h-screen flex flex-col">
        <div className="border-b p-4">
          <Button variant="ghost" size="sm" onClick={() => setMode('list')}>
            <ArrowLeft className="w-4 h-4 mr-2" />
            Back to Flows
          </Button>
        </div>
        <div className="flex-1 overflow-hidden">
          <FlowTester flow={selectedFlow} onTest={handleRunTest} />
        </div>
      </div>
    );
  }

  return (
    <div className="h-screen">
      <FlowList
        flows={flows}
        onFlowCreate={handleCreateFlow}
        onFlowEdit={handleEditFlow}
        onFlowDelete={handleDeleteFlow}
        onFlowDuplicate={handleDuplicateFlow}
        onFlowTest={handleTestFlow}
      />
    </div>
  );
}
"}

{"file_path": "src/app/admin/prompts/page.tsx", "initial_content": "/**
 * Admin Prompts Management Page
 * 
 * Page for managing prompt templates with create, edit, delete operations.
 */

'use client';

import React, { useState } from 'react';
import { PromptConfiguration } from '@/lib/models/prompt-config';
import { PromptList } from '@/components/admin/prompts/PromptList';
import { PromptEditor } from '@/components/admin/prompts/PromptEditor';
import { Button } from '@/components/ui/button';
import { Sheet, SheetContent } from '@/components/ui/sheet';
import { useToast } from '@/hooks/util/use-toast';
import { ArrowLeft } from 'lucide-react';

export default function AdminPromptsPage() {
  const [prompts, setPrompts] = useState<PromptConfiguration[]>([]);
  const [selectedPrompt, setSelectedPrompt] = useState<PromptConfiguration | null>(null);
  const [mode, setMode] = useState<'list' | 'edit'>('list');
  const [isLoading, setIsLoading] = useState(false);
  const { toast } = useToast();

  // Fetch prompts on mount
  React.useEffect(() => {
    fetchPrompts();
  }, []);

  const fetchPrompts = async () => {
    try {
      setIsLoading(true);
      const response = await fetch('/api/admin/prompts');
      if (!response.ok) throw new Error('Failed to fetch prompts');
      const data = await response.json();
      setPrompts(data.prompts || []);
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to load prompts',
        variant: 'destructive',
      });
    } finally {
      setIsLoading(false);
    }
  };

  const handleCreatePrompt = () => {
    setSelectedPrompt(null);
    setMode('edit');
  };

  const handleEditPrompt = (prompt: PromptConfiguration) => {
    setSelectedPrompt(prompt);
    setMode('edit');
  };

  const handleSavePrompt = async (promptData: Partial<PromptConfiguration>) => {
    try {
      const url = selectedPrompt?.id
        ? `/api/admin/prompts/${selectedPrompt.id}`
        : '/api/admin/prompts';

      const method = selectedPrompt?.id ? 'PUT' : 'POST';

      const response = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(promptData),
      });

      if (!response.ok) throw new Error('Failed to save prompt');

      toast({
        title: 'Success',
        description: `Prompt ${selectedPrompt?.id ? 'updated' : 'created'} successfully`,
      });

      await fetchPrompts();
      setMode('list');
      setSelectedPrompt(null);
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to save prompt',
        variant: 'destructive',
      });
    }
  };

  const handleDeletePrompt = async (promptId: string) => {
    if (!confirm('Are you sure you want to delete this prompt?')) return;

    try {
      const response = await fetch(`/api/admin/prompts/${promptId}`, {
        method: 'DELETE',
      });

      if (!response.ok) throw new Error('Failed to delete prompt');

      toast({
        title: 'Success',
        description: 'Prompt deleted successfully',
      });

      await fetchPrompts();
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to delete prompt',
        variant: 'destructive',
      });
    }
  };

  const handleDuplicatePrompt = async (prompt: PromptConfiguration) => {
    const duplicate = {
      ...prompt,
      name: `${prompt.name}-copy`,
      displayName: `${prompt.displayName} (Copy)`,
      status: 'draft' as const,
    };
    delete duplicate.id;

    try {
      const response = await fetch('/api/admin/prompts', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(duplicate),
      });

      if (!response.ok) throw new Error('Failed to duplicate prompt');

      toast({
        title: 'Success',
        description: 'Prompt duplicated successfully',
      });

      await fetchPrompts();
    } catch (error) {
      toast({
        title: 'Error',
        description: 'Failed to duplicate prompt',
        variant: 'destructive',
      });
    }
  };

  const handleTestPrompt = async (prompt: PromptConfiguration) => {
    toast({
      title: 'Test Prompt',
      description: 'Prompt testing feature coming soon',
    });
  };

  if (mode === 'edit') {
    return (
      <div className="h-screen flex flex-col">
        <div className="border-b p-4">
          <Button variant="ghost" size="sm" onClick={() => setMode('list')}>
            <ArrowLeft className="w-4 h-4 mr-2" />
            Back to Prompts
          </Button>
        </div>
        <div className="flex-1 overflow-hidden p-6">
          <div className="max-w-5xl mx-auto">
            <PromptEditor
              initialPrompt={selectedPrompt || undefined}
              onSave={handleSavePrompt}
              onTest={handleTestPrompt}
            />
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="h-screen">
      <PromptList
        prompts={prompts}
        onPromptCreate={handleCreatePrompt}
        onPromptEdit={handleEditPrompt}
        onPromptDelete={handleDeletePrompt}
        onPromptDuplicate={handleDuplicatePrompt}
        onPromptTest={handleTestPrompt}
      />
    </div>
  );
}
"}

