{"file_path": "scripts/migration/analyze-flows.ts", "initial_content": "/**
 * Flow Analysis Tool
 * 
 * Analyzes existing hardcoded flows and provides migration recommendations.
 * Identifies complexity, dependencies, and migration priority.
 */

import { readFileSync, readdirSync, statSync } from 'fs';
import { join } from 'path';
import { StepType } from '@/lib/models/flow-config';

interface FlowAnalysis {
  flowName: string;
  filePath: string;
  complexity: 'simple' | 'medium' | 'complex';
  estimatedSteps: number;
  dependencies: string[];
  usesRAG: boolean;
  usesTools: boolean;
  hasConditionals: boolean;
  hasLoops: boolean;
  promptsFound: number;
  migrationPriority: 'high' | 'medium' | 'low';
  migrationPhase: 1 | 2 | 3;
  recommendations: string[];
  estimatedEffort: string;
}

interface AnalysisReport {
  totalFlows: number;
  analyzedFlows: number;
  byComplexity: {
    simple: number;
    medium: number;
    complex: number;
  };
  byPhase: {
    phase1: number;
    phase2: number;
    phase3: number;
  };
  flows: FlowAnalysis[];
  summary: string[];
}

export class FlowAnalyzer {
  private flowsDir: string;
  private patterns = {
    ragRetrieval: /ragService|retrieveContext|vectorStore/gi,
    toolUsage: /executeTool|toolRegistry|callTool/gi,
    conditionals: /if\s*\(|switch\s*\(|\?\s*:/gi,
    loops: /for\s*\(|while\s*\(|\.map\(|\.forEach\(/gi,
    prompts: /prompt\s*[:=]|template\s*[:=]|`[\s\S]*?\$\{/gi,
    generateCall: /ai\.generate|model\.generate|llm\.generate/gi,
    errorHandling: /try\s*\{|catch\s*\(/gi,
  };

  constructor(flowsDir: string = './src/ai/flows') {
    this.flowsDir = flowsDir;
  }

  /**
   * Analyze all flows in the directory
   */
  public async analyzeAllFlows(): Promise<AnalysisReport> {
    console.log('🔍 Starting flow analysis...\n');

    const flowFiles = this.getFlowFiles();
    const analyses: FlowAnalysis[] = [];

    for (const file of flowFiles) {
      const analysis = await this.analyzeFlow(file);
      if (analysis) {
        analyses.push(analysis);
        this.printFlowAnalysis(analysis);
      }
    }

    const report = this.generateReport(analyses);
    return report;
  }

  /**
   * Get all TypeScript flow files
   */
  private getFlowFiles(): string[] {
    try {
      const files = readdirSync(this.flowsDir);
      return files
        .filter(file => file.endsWith('.ts') && !file.includes('.test.') && !file.includes('index.ts'))
        .map(file => join(this.flowsDir, file));
    } catch (error) {
      console.error('Error reading flows directory:', error);
      return [];
    }
  }

  /**
   * Analyze a single flow file
   */
  private async analyzeFlow(filePath: string): Promise<FlowAnalysis | null> {
    try {
      const content = readFileSync(filePath, 'utf-8');
      const flowName = this.extractFlowName(filePath);

      // Count occurrences of different patterns
      const usesRAG = this.patterns.ragRetrieval.test(content);
      const usesTools = this.patterns.toolUsage.test(content);
      const hasConditionals = this.patterns.conditionals.test(content);
      const hasLoops = this.patterns.loops.test(content);
      const promptMatches = content.match(this.patterns.prompts) || [];
      const generateCalls = content.match(this.patterns.generateCall) || [];

      // Estimate number of steps
      const estimatedSteps = this.estimateSteps(content, {
        usesRAG,
        usesTools,
        hasConditionals,
        hasLoops,
        generateCalls: generateCalls.length,
      });

      // Determine complexity
      const complexity = this.determineComplexity(estimatedSteps, {
        usesRAG,
        usesTools,
        hasConditionals,
        hasLoops,
      });

      // Find dependencies
      const dependencies = this.extractDependencies(content);

      // Determine migration priority and phase
      const { priority, phase } = this.determineMigrationStrategy(complexity, {
        usesRAG,
        usesTools,
        hasConditionals,
        hasLoops,
      });

      // Generate recommendations
      const recommendations = this.generateRecommendations({
        complexity,
        usesRAG,
        usesTools,
        hasConditionals,
        hasLoops,
        promptsFound: promptMatches.length,
      });

      // Estimate effort
      const estimatedEffort = this.estimateEffort(complexity, estimatedSteps);

      return {
        flowName,
        filePath,
        complexity,
        estimatedSteps,
        dependencies,
        usesRAG,
        usesTools,
        hasConditionals,
        hasLoops,
        promptsFound: promptMatches.length,
        migrationPriority: priority,
        migrationPhase: phase,
        recommendations,
        estimatedEffort,
      };
    } catch (error) {
      console.error(`Error analyzing ${filePath}:`, error);
      return null;
    }
  }

  /**
   * Extract flow name from file path
   */
  private extractFlowName(filePath: string): string {
    const fileName = filePath.split('/').pop() || '';
    return fileName.replace('.ts', '');
  }

  /**
   * Estimate number of steps in the flow
   */
  private estimateSteps(
    content: string,
    features: {
      usesRAG: boolean;
      usesTools: boolean;
      hasConditionals: boolean;
      hasLoops: boolean;
      generateCalls: number;
    }
  ): number {
    let steps = 0;

    // Base steps from generate calls
    steps += features.generateCalls;

    // Add steps for RAG
    if (features.usesRAG) steps += 1;

    // Add steps for tools
    if (features.usesTools) steps += 1;

    // Add steps for conditionals
    if (features.hasConditionals) steps += 2;

    // Add steps for loops
    if (features.hasLoops) steps += 2;

    // Minimum of 1 step
    return Math.max(1, steps);
  }

  /**
   * Determine flow complexity
   */
  private determineComplexity(
    steps: number,
    features: {
      usesRAG: boolean;
      usesTools: boolean;
      hasConditionals: boolean;
      hasLoops: boolean;
    }
  ): 'simple' | 'medium' | 'complex' {
    // Complex if has loops or many steps
    if (features.hasLoops || steps > 5) {
      return 'complex';
    }

    // Medium if has conditionals or RAG or tools
    if (features.hasConditionals || features.usesRAG || features.usesTools) {
      return 'medium';
    }

    // Simple otherwise
    return 'simple';
  }

  /**
   * Extract import dependencies
   */
  private extractDependencies(content: string): string[] {
    const importRegex = /import\s+.*?from\s+['"]([^'"]+)['"]/g;
    const dependencies = new Set<string>();

    let match;
    while ((match = importRegex.exec(content)) !== null) {
      const dep = match[1];
      // Only include project dependencies
      if (dep.startsWith('@/') || dep.startsWith('./') || dep.startsWith('../')) {
        dependencies.add(dep);
      }
    }

    return Array.from(dependencies);
  }

  /**
   * Determine migration priority and phase
   */
  private determineMigrationStrategy(
    complexity: 'simple' | 'medium' | 'complex',
    features: {
      usesRAG: boolean;
      usesTools: boolean;
      hasConditionals: boolean;
      hasLoops: boolean;
    }
  ): { priority: 'high' | 'medium' | 'low'; phase: 1 | 2 | 3 } {
    // Phase 1: Simple text generation flows
    if (complexity === 'simple' && !features.usesRAG && !features.usesTools) {
      return { priority: 'high', phase: 1 };
    }

    // Phase 2: Analysis and RAG flows
    if (complexity === 'medium' || features.usesRAG) {
      return { priority: 'medium', phase: 2 };
    }

    // Phase 3: Complex flows with control flow
    return { priority: 'low', phase: 3 };
  }

  /**
   * Generate migration recommendations
   */
  private generateRecommendations(analysis: {
    complexity: string;
    usesRAG: boolean;
    usesTools: boolean;
    hasConditionals: boolean;
    hasLoops: boolean;
    promptsFound: number;
  }): string[] {
    const recommendations: string[] = [];

    if (analysis.complexity === 'simple') {
      recommendations.push('✅ Good candidate for early migration');
      recommendations.push('📝 Extract prompts into prompt templates');
    }

    if (analysis.usesRAG) {
      recommendations.push('🔍 Add RETRIEVE step for RAG context');
      recommendations.push('⚙️ Configure collection and topK parameters');
    }

    if (analysis.usesTools) {
      recommendations.push('🔧 Register custom tools in tool registry');
      recommendations.push('📋 Define tool input/output schemas');
    }

    if (analysis.hasConditionals) {
      recommendations.push('🔀 Use CONDITION steps for branching logic');
      recommendations.push('⚠️ Test both branches thoroughly');
    }

    if (analysis.hasLoops) {
      recommendations.push('🔄 Convert loops to LOOP steps');
      recommendations.push('⚠️ Set appropriate maxIterations');
    }

    if (analysis.promptsFound > 1) {
      recommendations.push(`📚 Extract ${analysis.promptsFound} prompts into templates`);
    }

    if (analysis.complexity === 'complex') {
      recommendations.push('🧪 Migrate in pilot phase first');
      recommendations.push('📊 Compare outputs carefully');
    }

    return recommendations;
  }

  /**
   * Estimate migration effort
   */
  private estimateEffort(complexity: string, steps: number): string {
    if (complexity === 'simple') {
      return '1-2 hours';
    } else if (complexity === 'medium') {
      return '2-4 hours';
    } else {
      return '4-8 hours';
    }
  }

  /**
   * Print individual flow analysis
   */
  private printFlowAnalysis(analysis: FlowAnalysis): void {
    const complexityEmoji = {
      simple: '🟢',
      medium: '🟡',
      complex: '🔴',
    };

    console.log(`\n${complexityEmoji[analysis.complexity]} ${analysis.flowName}`);
    console.log(`   Complexity: ${analysis.complexity.toUpperCase()}`);
    console.log(`   Estimated Steps: ${analysis.estimatedSteps}`);
    console.log(`   Migration Phase: ${analysis.migrationPhase}`);
    console.log(`   Priority: ${analysis.migrationPriority.toUpperCase()}`);
    console.log(`   Effort: ${analysis.estimatedEffort}`);

    if (analysis.usesRAG || analysis.usesTools || analysis.hasConditionals || analysis.hasLoops) {
      console.log(`   Features:`);
      if (analysis.usesRAG) console.log(`     • RAG retrieval`);
      if (analysis.usesTools) console.log(`     • Tool usage`);
      if (analysis.hasConditionals) console.log(`     • Conditional logic`);
      if (analysis.hasLoops) console.log(`     • Loops/iteration`);
    }

    if (analysis.recommendations.length > 0) {
      console.log(`   Recommendations:`);
      analysis.recommendations.forEach(rec => console.log(`     ${rec}`));
    }
  }

  /**
   * Generate comprehensive analysis report
   */
  private generateReport(analyses: FlowAnalysis[]): AnalysisReport {
    const byComplexity = {
      simple: analyses.filter(a => a.complexity === 'simple').length,
      medium: analyses.filter(a => a.complexity === 'medium').length,
      complex: analyses.filter(a => a.complexity === 'complex').length,
    };

    const byPhase = {
      phase1: analyses.filter(a => a.migrationPhase === 1).length,
      phase2: analyses.filter(a => a.migrationPhase === 2).length,
      phase3: analyses.filter(a => a.migrationPhase === 3).length,
    };

    const summary = [
      `📊 Analysis Summary:`,
      `   Total Flows: ${analyses.length}`,
      ``,
      `   By Complexity:`,
      `   🟢 Simple: ${byComplexity.simple}`,
      `   🟡 Medium: ${byComplexity.medium}`,
      `   🔴 Complex: ${byComplexity.complex}`,
      ``,
      `   By Migration Phase:`,
      `   Phase 1 (Simple): ${byPhase.phase1} flows`,
      `   Phase 2 (Medium): ${byPhase.phase2} flows`,
      `   Phase 3 (Complex): ${byPhase.phase3} flows`,
      ``,
      `   Total Estimated Effort: ${this.calculateTotalEffort(analyses)}`,
    ];

    return {
      totalFlows: analyses.length,
      analyzedFlows: analyses.length,
      byComplexity,
      byPhase,
      flows: analyses,
      summary,
    };
  }

  /**
   * Calculate total effort across all flows
   */
  private calculateTotalEffort(analyses: FlowAnalysis[]): string {
    const hours = analyses.reduce((total, analysis) => {
      const effort = analysis.estimatedEffort.match(/(\d+)-(\d+)/);
      if (effort) {
        return total + (parseInt(effort[1]) + parseInt(effort[2])) / 2;
      }
      return total;
    }, 0);

    return `${Math.round(hours)} hours`;
  }

  /**
   * Export report to JSON
   */
  public exportReport(report: AnalysisReport, outputPath: string): void {
    const fs = require('fs');
    fs.writeFileSync(outputPath, JSON.stringify(report, null, 2));
    console.log(`\n✅ Report exported to ${outputPath}`);
  }

  /**
   * Print summary report
   */
  public printSummary(report: AnalysisReport): void {
    console.log('\n' + '='.repeat(70));
    report.summary.forEach(line => console.log(line));
    console.log('='.repeat(70) + '\n');
  }
}

// CLI Usage
if (require.main === module) {
  const analyzer = new FlowAnalyzer();

  analyzer.analyzeAllFlows().then(report => {
    analyzer.printSummary(report);
    analyzer.exportReport(report, './migration-analysis-report.json');

    console.log('✨ Analysis complete!');
    console.log('📄 Detailed report saved to migration-analysis-report.json');
  }).catch(error => {
    console.error('❌ Analysis failed:', error);
    process.exit(1);
  });
}

export default FlowAnalyzer;
"}

{"file_path": "scripts/migration/extract-prompts.ts", "initial_content": "/**
 * Prompt Extraction Script
 * 
 * Extracts prompt templates from existing hardcoded flows and converts them
 * to PromptConfiguration objects with variable definitions.
 */

import { readFileSync, writeFileSync } from 'fs';
import { PromptConfiguration, PromptVariable } from '@/lib/models/prompt-config';

interface ExtractedPrompt {
  sourceFlow: string;
  promptContent: string;
  variables: string[];
  location: {
    line: number;
    column: number;
  };
  context: string;
}

interface ExtractionResult {
  flowName: string;
  filePath: string;
  prompts: ExtractedPrompt[];
  configurations: PromptConfiguration[];
}

export class PromptExtractor {
  private patterns = {
    // Template literal with variables: `text ${variable}`
    templateLiteral: /`([^`]*\$\{[^}]+\}[^`]*)`/gs,
    // String concatenation: 'text' + variable + 'text'
    stringConcat: /(['"])([^'"]*)\1\s*\+\s*(\w+)/g,
    // Variable extraction from template: ${variable}
    variables: /\$\{([^}]+)\}/g,
    // Mustache/Handlebars syntax: {{variable}}
    mustache: /\{\{([^}]+)\}\}/g,
  };

  /**
   * Extract prompts from a flow file
   */
  public async extractFromFile(filePath: string): Promise<ExtractionResult> {
    const content = readFileSync(filePath, 'utf-8');
    const flowName = this.getFlowName(filePath);
    const lines = content.split('\n');

    const prompts = this.findPrompts(content, lines);
    const configurations = prompts.map((prompt, index) => 
      this.createPromptConfiguration(prompt, flowName, index)
    );

    return {
      flowName,
      filePath,
      prompts,
      configurations,
    };
  }

  /**
   * Extract flow name from file path
   */
  private getFlowName(filePath: string): string {
    const fileName = filePath.split('/').pop() || '';
    return fileName.replace('.ts', '');
  }

  /**
   * Find all prompts in the content
   */
  private findPrompts(content: string, lines: string[]): ExtractedPrompt[] {
    const prompts: ExtractedPrompt[] = [];

    // Find template literals with variables
    let match;
    this.patterns.templateLiteral.lastIndex = 0;

    while ((match = this.patterns.templateLiteral.exec(content)) !== null) {
      const promptContent = match[1];
      const variables = this.extractVariables(promptContent);

      // Skip if no variables (likely not a prompt)
      if (variables.length === 0) continue;

      // Skip very short strings (likely not prompts)
      if (promptContent.length < 20) continue;

      const location = this.getLocation(content, match.index, lines);
      const context = this.getContext(lines, location.line);

      prompts.push({
        sourceFlow: '',
        promptContent,
        variables,
        location,
        context,
      });
    }

    return prompts;
  }

  /**
   * Extract variables from prompt content
   */
  private extractVariables(content: string): string[] {
    const variables = new Set<string>();

    // Extract ${variable} style
    let match;
    this.patterns.variables.lastIndex = 0;
    while ((match = this.patterns.variables.exec(content)) !== null) {
      const varName = match[1].trim();
      // Clean up variable name (remove object access, function calls, etc.)
      const cleanName = varName.split('.')[0].split('(')[0];
      if (cleanName) {
        variables.add(cleanName);
      }
    }

    // Extract {{variable}} style
    this.patterns.mustache.lastIndex = 0;
    while ((match = this.patterns.mustache.exec(content)) !== null) {
      const varName = match[1].trim();
      const cleanName = varName.split('.')[0];
      if (cleanName) {
        variables.add(cleanName);
      }
    }

    return Array.from(variables);
  }

  /**
   * Get line and column location in source
   */
  private getLocation(content: string, index: number, lines: string[]): { line: number; column: number } {
    const beforeMatch = content.substring(0, index);
    const line = beforeMatch.split('\n').length;
    const lastLineStart = beforeMatch.lastIndexOf('\n') + 1;
    const column = index - lastLineStart;

    return { line, column };
  }

  /**
   * Get context around the prompt (3 lines before and after)
   */
  private getContext(lines: string[], lineNumber: number): string {
    const start = Math.max(0, lineNumber - 3);
    const end = Math.min(lines.length, lineNumber + 3);
    return lines.slice(start, end).join('\n');
  }

  /**
   * Create PromptConfiguration from extracted prompt
   */
  private createPromptConfiguration(
    prompt: ExtractedPrompt,
    flowName: string,
    index: number
  ): PromptConfiguration {
    const promptName = this.generatePromptName(flowName, index);
    const variables = this.createVariables(prompt.variables);
    const templateContent = this.convertToMustacheSyntax(prompt.promptContent);

    return {
      name: promptName,
      displayName: this.generateDisplayName(flowName, index),
      description: `Extracted from ${flowName}`,
      category: this.categorizePrompt(prompt.promptContent),
      tags: [flowName, 'extracted', 'migration'],
      templateContent,
      variables,
      inputSchema: this.generateInputSchema(variables),
      outputSchema: {
        type: 'object',
        properties: {
          text: { type: 'string' },
        },
      },
      model: 'gemini-2.0-flash-exp',
      temperature: 0.7,
      maxTokens: 2048,
      status: 'draft',
      version: '1.0.0',
      metadata: {
        sourceFlow: flowName,
        extractedAt: new Date().toISOString(),
        location: prompt.location,
      },
    };
  }

  /**
   * Generate prompt name
   */
  private generatePromptName(flowName: string, index: number): string {
    return `${flowName}-prompt-${index + 1}`;
  }

  /**
   * Generate display name
   */
  private generateDisplayName(flowName: string, index: number): string {
    const formatted = flowName
      .split('-')
      .map(word => word.charAt(0).toUpperCase() + word.slice(1))
      .join(' ');
    return `${formatted} - Prompt ${index + 1}`;
  }

  /**
   * Create variable definitions from variable names
   */
  private createVariables(variableNames: string[]): PromptVariable[] {
    return variableNames.map(name => ({
      name,
      type: this.inferVariableType(name),
      description: `Variable ${name} from source flow`,
      required: true,
      defaultValue: undefined,
    }));
  }

  /**
   * Infer variable type from name
   */
  private inferVariableType(name: string): 'string' | 'number' | 'boolean' | 'array' | 'object' {
    const lowerName = name.toLowerCase();

    if (lowerName.includes('count') || lowerName.includes('number') || lowerName.includes('num')) {
      return 'number';
    }

    if (lowerName.includes('is') || lowerName.includes('has') || lowerName.includes('enabled')) {
      return 'boolean';
    }

    if (lowerName.includes('list') || lowerName.includes('items') || lowerName.includes('array')) {
      return 'array';
    }

    if (lowerName.includes('config') || lowerName.includes('settings') || lowerName.includes('options')) {
      return 'object';
    }

    return 'string';
  }

  /**
   * Convert template literal syntax to Mustache syntax
   */
  private convertToMustacheSyntax(content: string): string {
    // Convert ${variable} to {{variable}}
    return content.replace(/\$\{([^}]+)\}/g, '{{$1}}');
  }

  /**
   * Categorize prompt based on content
   */
  private categorizePrompt(content: string): string {
    const lowerContent = content.toLowerCase();

    if (lowerContent.includes('report') || lowerContent.includes('document')) {
      return 'report-generation';
    }

    if (lowerContent.includes('analyze') || lowerContent.includes('analysis')) {
      return 'analysis';
    }

    if (lowerContent.includes('summarize') || lowerContent.includes('summary')) {
      return 'summarization';
    }

    if (lowerContent.includes('translate')) {
      return 'translation';
    }

    if (lowerContent.includes('improve') || lowerContent.includes('enhance')) {
      return 'improvement';
    }

    return 'general';
  }

  /**
   * Generate input schema from variables
   */
  private generateInputSchema(variables: PromptVariable[]): any {
    const properties: Record<string, any> = {};
    const required: string[] = [];

    variables.forEach(variable => {
      properties[variable.name] = {
        type: variable.type,
        description: variable.description,
      };

      if (variable.required) {
        required.push(variable.name);
      }
    });

    return {
      type: 'object',
      properties,
      required,
    };
  }

  /**
   * Extract prompts from multiple files
   */
  public async extractFromMultipleFiles(filePaths: string[]): Promise<ExtractionResult[]> {
    const results: ExtractionResult[] = [];

    for (const filePath of filePaths) {
      try {
        const result = await this.extractFromFile(filePath);
        if (result.prompts.length > 0) {
          results.push(result);
        }
      } catch (error) {
        console.error(`Error extracting from ${filePath}:`, error);
      }
    }

    return results;
  }

  /**
   * Export prompt configurations to JSON
   */
  public exportConfigurations(
    results: ExtractionResult[],
    outputPath: string
  ): void {
    const allConfigurations = results.flatMap(r => r.configurations);

    writeFileSync(
      outputPath,
      JSON.stringify(allConfigurations, null, 2),
      'utf-8'
    );

    console.log(`✅ Exported ${allConfigurations.length} prompt configurations to ${outputPath}`);
  }

  /**
   * Generate migration report
   */
  public generateReport(results: ExtractionResult[]): string {
    const totalPrompts = results.reduce((sum, r) => sum + r.prompts.length, 0);
    const flowsWithPrompts = results.length;

    let report = `
╔══════════════════════════════════════════════════════════════════════╗
║                    PROMPT EXTRACTION REPORT                          ║
╚══════════════════════════════════════════════════════════════════════╝

📊 Summary:
   Total Flows Analyzed: ${results.length}
   Flows with Prompts: ${flowsWithPrompts}
   Total Prompts Extracted: ${totalPrompts}

📋 Extraction Details:
`;

    results.forEach(result => {
      report += `\n   ${result.flowName}:`;
      report += `\n      Prompts Found: ${result.prompts.length}`;

      result.prompts.forEach((prompt, index) => {
        report += `\n      • Prompt ${index + 1}:`;
        report += `\n        Variables: ${prompt.variables.join(', ')}`;
        report += `\n        Location: Line ${prompt.location.line}`;
        report += `\n        Length: ${prompt.promptContent.length} chars`;
      });
    });

    report += `\n\n✨ Next Steps:`;
    report += `\n   1. Review generated prompt configurations`;
    report += `\n   2. Refine variable names and types`;
    report += `\n   3. Add descriptions and examples`;
    report += `\n   4. Test prompts with sample data`;
    report += `\n   5. Upload to prompt management system`;

    return report;
  }

  /**
   * Print extraction summary
   */
  public printSummary(results: ExtractionResult[]): void {
    console.log('\n' + '='.repeat(70));
    console.log(this.generateReport(results));
    console.log('='.repeat(70) + '\n');
  }
}

// CLI Usage
if (require.main === module) {
  const { readdirSync } = require('fs');
  const { join } = require('path');

  const flowsDir = './src/ai/flows';
  const files = readdirSync(flowsDir)
    .filter((f: string) => f.endsWith('.ts') && !f.includes('.test.') && !f.includes('index.ts'))
    .map((f: string) => join(flowsDir, f));

  const extractor = new PromptExtractor();

  extractor.extractFromMultipleFiles(files).then(results => {
    extractor.printSummary(results);
    extractor.exportConfigurations(results, './extracted-prompts.json');

    console.log('✨ Prompt extraction complete!');
    console.log('📄 Configurations saved to extracted-prompts.json');
  }).catch(error => {
    console.error('❌ Extraction failed:', error);
    process.exit(1);
  });
}

export default PromptExtractor;
"}

{"file_path": "scripts/migration/generate-config.ts", "initial_content": "/**
 * Config Generation Script
 * 
 * Generates FlowConfiguration objects from analyzed flows.
 * Creates step-by-step flow definitions with proper schemas.
 */

import { readFileSync, writeFileSync } from 'fs';
import {
  FlowConfiguration,
  FlowStep,
  StepType,
  GenerateStepConfig,
  RetrieveStepConfig,
  ToolStepConfig,
  FormatStepConfig,
} from '@/lib/models/flow-config';

interface FlowTemplate {
  flowName: string;
  displayName: string;
  description: string;
  category: string;
  tags: string[];
  steps: StepTemplate[];
  inputSchema: any;
  outputSchema: any;
}

interface StepTemplate {
  type: StepType;
  name: string;
  description: string;
  config: any;
}

export class ConfigGenerator {
  /**
   * Generate FlowConfiguration from analyzed flow
   */
  public generateFlowConfig(
    flowName: string,
    analysis: any,
    prompts: any[]
  ): FlowConfiguration {
    const steps = this.generateSteps(flowName, analysis, prompts);

    return {
      name: flowName,
      displayName: this.formatDisplayName(flowName),
      description: this.generateDescription(flowName, analysis),
      category: this.categorizeFlow(flowName, analysis),
      tags: this.generateTags(flowName, analysis),
      steps,
      inputSchema: this.generateInputSchema(steps),
      outputSchema: this.generateOutputSchema(steps),
      status: 'draft',
      version: '1.0.0',
      metadata: {
        migratedFrom: flowName,
        migratedAt: new Date().toISOString(),
        originalComplexity: analysis.complexity,
      },
    };
  }

  /**
   * Generate steps based on flow analysis
   */
  private generateSteps(
    flowName: string,
    analysis: any,
    prompts: any[]
  ): FlowStep[] {
    const steps: FlowStep[] = [];
    let stepCounter = 1;

    // Add RAG retrieval step if needed
    if (analysis.usesRAG) {
      steps.push(this.createRetrieveStep(stepCounter++, flowName));
    }

    // Add generate steps for each prompt
    prompts.forEach((prompt, index) => {
      steps.push(this.createGenerateStep(stepCounter++, flowName, prompt, index));
    });

    // Add tool step if needed
    if (analysis.usesTools) {
      steps.push(this.createToolStep(stepCounter++, flowName));
    }

    // Add format step
    steps.push(this.createFormatStep(stepCounter++, flowName));

    // If no steps were generated, add a default generate step
    if (steps.length === 0) {
      steps.push(this.createDefaultGenerateStep(flowName));
    }

    return steps;
  }

  /**
   * Create RETRIEVE step for RAG
   */
  private createRetrieveStep(stepNum: number, flowName: string): FlowStep {
    const config: RetrieveStepConfig = {
      type: 'RETRIEVE',
      query: '{{input.query}}',
      collection: 'documents',
      topK: 5,
      threshold: 0.7,
      rerank: true,
    };

    return {
      id: `${flowName}-step-${stepNum}`,
      type: 'RETRIEVE',
      name: 'Retrieve Context',
      description: 'Retrieve relevant context from RAG database',
      config,
      inputSchema: {
        type: 'object',
        properties: {
          query: { type: 'string' },
        },
        required: ['query'],
      },
      outputSchema: {
        type: 'object',
        properties: {
          context: { type: 'string' },
          sources: { type: 'array' },
        },
      },
    };
  }

  /**
   * Create GENERATE step
   */
  private createGenerateStep(
    stepNum: number,
    flowName: string,
    prompt: any,
    promptIndex: number
  ): FlowStep {
    const promptName = prompt?.name || `${flowName}-prompt-${promptIndex + 1}`;

    const config: GenerateStepConfig = {
      type: 'GENERATE',
      promptName,
      model: 'gemini-2.0-flash-exp',
      temperature: 0.7,
      maxTokens: 2048,
      variables: this.extractPromptVariables(prompt),
    };

    return {
      id: `${flowName}-step-${stepNum}`,
      type: 'GENERATE',
      name: `Generate Content ${promptIndex + 1}`,
      description: `Generate content using ${promptName}`,
      config,
      inputSchema: {
        type: 'object',
        properties: this.generateVariableProperties(prompt?.variables || []),
        required: prompt?.variables?.filter((v: any) => v.required).map((v: any) => v.name) || [],
      },
      outputSchema: {
        type: 'object',
        properties: {
          text: { type: 'string' },
          metadata: { type: 'object' },
        },
      },
    };
  }

  /**
   * Create TOOL step
   */
  private createToolStep(stepNum: number, flowName: string): FlowStep {
    const config: ToolStepConfig = {
      type: 'TOOL',
      toolName: 'custom-tool',
      arguments: {
        input: '{{context.previousOutput}}',
      },
    };

    return {
      id: `${flowName}-step-${stepNum}`,
      type: 'TOOL',
      name: 'Execute Tool',
      description: 'Execute custom tool for processing',
      config,
      inputSchema: {
        type: 'object',
        properties: {
          previousOutput: { type: 'string' },
        },
      },
      outputSchema: {
        type: 'object',
        properties: {
          result: { type: 'any' },
        },
      },
    };
  }

  /**
   * Create FORMAT step
   */
  private createFormatStep(stepNum: number, flowName: string): FlowStep {
    const config: FormatStepConfig = {
      type: 'FORMAT',
      format: 'markdown',
      template: '{{context.text}}',
    };

    return {
      id: `${flowName}-step-${stepNum}`,
      type: 'FORMAT',
      name: 'Format Output',
      description: 'Format final output',
      config,
      inputSchema: {
        type: 'object',
        properties: {
          text: { type: 'string' },
        },
      },
      outputSchema: {
        type: 'object',
        properties: {
          formatted: { type: 'string' },
        },
      },
    };
  }

  /**
   * Create default GENERATE step
   */
  private createDefaultGenerateStep(flowName: string): FlowStep {
    const config: GenerateStepConfig = {
      type: 'GENERATE',
      promptName: `${flowName}-prompt`,
      model: 'gemini-2.0-flash-exp',
      temperature: 0.7,
      maxTokens: 2048,
      variables: {
        input: '{{input.text}}',
      },
    };

    return {
      id: `${flowName}-step-1`,
      type: 'GENERATE',
      name: 'Generate Content',
      description: 'Generate content based on input',
      config,
      inputSchema: {
        type: 'object',
        properties: {
          text: { type: 'string' },
        },
        required: ['text'],
      },
      outputSchema: {
        type: 'object',
        properties: {
          text: { type: 'string' },
        },
      },
    };
  }

  /**
   * Extract prompt variables for step config
   */
  private extractPromptVariables(prompt: any): Record<string, string> {
    if (!prompt?.variables) return {};

    const variables: Record<string, string> = {};
    prompt.variables.forEach((v: any) => {
      variables[v.name] = `{{context.${v.name}}}`;
    });

    return variables;
  }

  /**
   * Generate variable properties for schema
   */
  private generateVariableProperties(variables: any[]): Record<string, any> {
    const properties: Record<string, any> = {};

    variables.forEach(v => {
      properties[v.name] = {
        type: v.type || 'string',
        description: v.description,
      };
    });

    return properties;
  }

  /**
   * Format display name from flow name
   */
  private formatDisplayName(flowName: string): string {
    return flowName
      .split('-')
      .map(word => word.charAt(0).toUpperCase() + word.slice(1))
      .join(' ');
  }

  /**
   * Generate description from flow name and analysis
   */
  private generateDescription(flowName: string, analysis: any): string {
    const displayName = this.formatDisplayName(flowName);
    let description = `${displayName} flow - `;

    if (analysis.usesRAG) {
      description += 'retrieves context and ';
    }

    description += 'generates content';

    if (analysis.usesTools) {
      description += ' using custom tools';
    }

    return description + '.';
  }

  /**
   * Categorize flow based on name and analysis
   */
  private categorizeFlow(flowName: string, analysis: any): string {
    const lowerName = flowName.toLowerCase();

    if (lowerName.includes('report') || lowerName.includes('document')) {
      return 'report-generation';
    }

    if (lowerName.includes('analyze') || lowerName.includes('checker')) {
      return 'analysis';
    }

    if (lowerName.includes('summarize')) {
      return 'summarization';
    }

    if (lowerName.includes('translate')) {
      return 'translation';
    }

    if (lowerName.includes('improve') || lowerName.includes('paraphrase')) {
      return 'improvement';
    }

    return 'general';
  }

  /**
   * Generate tags from flow name and analysis
   */
  private generateTags(flowName: string, analysis: any): string[] {
    const tags: string[] = ['migrated'];

    if (analysis.usesRAG) tags.push('rag');
    if (analysis.usesTools) tags.push('tools');
    if (analysis.hasConditionals) tags.push('conditional');
    if (analysis.hasLoops) tags.push('loop');

    // Add category-based tags
    const category = this.categorizeFlow(flowName, analysis);
    tags.push(category);

    return tags;
  }

  /**
   * Generate input schema from steps
   */
  private generateInputSchema(steps: FlowStep[]): any {
    // Use input schema from first step
    const firstStep = steps[0];
    if (!firstStep) {
      return {
        type: 'object',
        properties: {
          input: { type: 'string' },
        },
      };
    }

    return firstStep.inputSchema;
  }

  /**
   * Generate output schema from steps
   */
  private generateOutputSchema(steps: FlowStep[]): any {
    // Use output schema from last step
    const lastStep = steps[steps.length - 1];
    if (!lastStep) {
      return {
        type: 'object',
        properties: {
          output: { type: 'string' },
        },
      };
    }

    return lastStep.outputSchema;
  }

  /**
   * Generate multiple flow configurations
   */
  public generateMultipleConfigs(
    analysisResults: any[],
    promptResults: any[]
  ): FlowConfiguration[] {
    const configs: FlowConfiguration[] = [];

    analysisResults.forEach(analysis => {
      // Find prompts for this flow
      const flowPrompts = promptResults.find(
        p => p.flowName === analysis.flowName
      )?.configurations || [];

      const config = this.generateFlowConfig(
        analysis.flowName,
        analysis,
        flowPrompts
      );

      configs.push(config);
    });

    return configs;
  }

  /**
   * Export configurations to JSON
   */
  public exportConfigs(configs: FlowConfiguration[], outputPath: string): void {
    writeFileSync(
      outputPath,
      JSON.stringify(configs, null, 2),
      'utf-8'
    );

    console.log(`✅ Exported ${configs.length} flow configurations to ${outputPath}`);
  }

  /**
   * Generate migration report
   */
  public generateReport(configs: FlowConfiguration[]): string {
    let report = `
╔══════════════════════════════════════════════════════════════════════╗
║                   CONFIG GENERATION REPORT                           ║
╚══════════════════════════════════════════════════════════════════════╝

📊 Summary:
   Total Configurations Generated: ${configs.length}
   Total Steps: ${configs.reduce((sum, c) => sum + c.steps.length, 0)}

📋 Configuration Details:
`;

    configs.forEach(config => {
      report += `\n   ${config.name}:`;
      report += `\n      Display Name: ${config.displayName}`;
      report += `\n      Category: ${config.category}`;
      report += `\n      Steps: ${config.steps.length}`;
      report += `\n      Status: ${config.status}`;

      // List step types
      const stepTypes = config.steps.map(s => s.type).join(' → ');
      report += `\n      Flow: ${stepTypes}`;
    });

    report += `\n\n✨ Next Steps:`;
    report += `\n   1. Review generated configurations`;
    report += `\n   2. Adjust step parameters`;
    report += `\n   3. Test each configuration`;
    report += `\n   4. Upload to Firestore`;
    report += `\n   5. Deploy to production`;

    return report;
  }

  /**
   * Print summary
   */
  public printSummary(configs: FlowConfiguration[]): void {
    console.log('\n' + '='.repeat(70));
    console.log(this.generateReport(configs));
    console.log('='.repeat(70) + '\n');
  }

  /**
   * Generate TypeScript code for flow configurations
   */
  public generateTypeScriptCode(configs: FlowConfiguration[]): string {
    let code = `/**
 * Generated Flow Configurations
 * 
 * Auto-generated from migration tool
 * Date: ${new Date().toISOString()}
 */

import { FlowConfiguration } from '@/lib/models/flow-config';

export const migratedFlows: FlowConfiguration[] = ${JSON.stringify(configs, null, 2)};

export default migratedFlows;
`;

    return code;
  }

  /**
   * Export as TypeScript file
   */
  public exportAsTypeScript(configs: FlowConfiguration[], outputPath: string): void {
    const code = this.generateTypeScriptCode(configs);
    writeFileSync(outputPath, code, 'utf-8');
    console.log(`✅ Exported TypeScript code to ${outputPath}`);
  }
}

// CLI Usage
if (require.main === module) {
  const analysisPath = './migration-analysis-report.json';
  const promptsPath = './extracted-prompts.json';

  try {
    const analysisData = JSON.parse(readFileSync(analysisPath, 'utf-8'));
    const promptsData = JSON.parse(readFileSync(promptsPath, 'utf-8'));

    const generator = new ConfigGenerator();
    const configs = generator.generateMultipleConfigs(
      analysisData.flows || [],
      promptsData
    );

    generator.printSummary(configs);
    generator.exportConfigs(configs, './generated-flow-configs.json');
    generator.exportAsTypeScript(configs, './generated-flow-configs.ts');

    console.log('✨ Config generation complete!');
    console.log('📄 Configurations saved to generated-flow-configs.json and .ts');
  } catch (error) {
    console.error('❌ Config generation failed:', error);
    console.error('Make sure analysis and prompt extraction have been run first.');
    process.exit(1);
  }
}

export default ConfigGenerator;
"}

{"file_path": "scripts/migration/migrate-flows.ts", "initial_content": "/**
 * Batch Migration Script
 * 
 * Orchestrates the complete migration process:
 * 1. Analyze flows
 * 2. Extract prompts
 * 3. Generate configurations
 * 4. Upload to Firestore
 * 5. Validate migration
 */

import { initializeApp } from 'firebase/app';
import { getFirestore, collection, doc, setDoc, getDocs } from 'firebase/firestore';
import FlowAnalyzer from './analyze-flows';
import PromptExtractor from './extract-prompts';
import ConfigGenerator from './generate-config';
import { FlowConfiguration } from '@/lib/models/flow-config';
import { PromptConfiguration } from '@/lib/models/prompt-config';
import { writeFileSync, readFileSync, readdirSync } from 'fs';
import { join } from 'path';

interface MigrationOptions {
  flowsDir?: string;
  phase?: 1 | 2 | 3 | 'all';
  dryRun?: boolean;
  outputDir?: string;
  skipAnalysis?: boolean;
  skipExtraction?: boolean;
  skipUpload?: boolean;
}

interface MigrationResult {
  success: boolean;
  flowsMigrated: number;
  promptsCreated: number;
  errors: string[];
  warnings: string[];
  duration: number;
  summary: string;
}

export class BatchMigrator {
  private flowsDir: string;
  private outputDir: string;
  private db: any;

  constructor(options: MigrationOptions = {}) {
    this.flowsDir = options.flowsDir || './src/ai/flows';
    this.outputDir = options.outputDir || './migration-output';

    // Initialize Firebase (only if not dry run)
    if (!options.dryRun && !options.skipUpload) {
      this.initializeFirebase();
    }
  }

  /**
   * Initialize Firebase
   */
  private initializeFirebase(): void {
    try {
      // Load Firebase config
      const firebaseConfig = JSON.parse(
        readFileSync('./firebase-config.json', 'utf-8')
      );

      const app = initializeApp(firebaseConfig);
      this.db = getFirestore(app);

      console.log('✅ Firebase initialized');
    } catch (error) {
      console.warn('⚠️  Firebase initialization failed. Running in dry-run mode.');
      this.db = null;
    }
  }

  /**
   * Run complete migration
   */
  public async migrate(options: MigrationOptions = {}): Promise<MigrationResult> {
    const startTime = Date.now();
    const errors: string[] = [];
    const warnings: string[] = [];

    console.log('\n╔══════════════════════════════════════════════════════════════════════╗');
    console.log('║                    BATCH MIGRATION STARTED                           ║');
    console.log('╚══════════════════════════════════════════════════════════════════════╝\n');

    try {
      // Step 1: Analyze flows
      let analysisReport;
      if (!options.skipAnalysis) {
        console.log('📊 Step 1: Analyzing flows...\n');
        analysisReport = await this.analyzeFlows();
        this.saveReport('analysis', analysisReport);
        console.log(`✅ Analysis complete: ${analysisReport.flows.length} flows analyzed\n`);
      } else {
        console.log('⏭️  Skipping analysis (loading from file)...\n');
        analysisReport = this.loadReport('analysis');
      }

      // Filter flows by phase
      const flowsToMigrate = this.filterFlowsByPhase(
        analysisReport.flows,
        options.phase || 'all'
      );

      console.log(`🎯 Migrating ${flowsToMigrate.length} flows (Phase ${options.phase || 'all'})\n`);

      // Step 2: Extract prompts
      let promptResults;
      if (!options.skipExtraction) {
        console.log('📝 Step 2: Extracting prompts...\n');
        promptResults = await this.extractPrompts(flowsToMigrate);
        this.saveReport('prompts', promptResults);
        console.log(`✅ Extraction complete: ${this.countPrompts(promptResults)} prompts extracted\n`);
      } else {
        console.log('⏭️  Skipping extraction (loading from file)...\n');
        promptResults = this.loadReport('prompts');
      }

      // Step 3: Generate configurations
      console.log('⚙️  Step 3: Generating configurations...\n');
      const { flowConfigs, promptConfigs } = await this.generateConfigs(
        flowsToMigrate,
        promptResults
      );
      this.saveReport('flow-configs', flowConfigs);
      this.saveReport('prompt-configs', promptConfigs);
      console.log(`✅ Generation complete: ${flowConfigs.length} flow configs, ${promptConfigs.length} prompt configs\n`);

      // Step 4: Upload to Firestore
      let uploadedFlows = 0;
      let uploadedPrompts = 0;

      if (!options.skipUpload && !options.dryRun) {
        console.log('☁️  Step 4: Uploading to Firestore...\n');

        uploadedPrompts = await this.uploadPrompts(promptConfigs);
        console.log(`✅ Uploaded ${uploadedPrompts} prompts`);

        uploadedFlows = await this.uploadFlows(flowConfigs);
        console.log(`✅ Uploaded ${uploadedFlows} flows\n`);
      } else {
        console.log('⏭️  Skipping upload (dry run mode)\n');
      }

      // Step 5: Validation
      console.log('🔍 Step 5: Validating migration...\n');
      const validationResults = await this.validateMigration(flowConfigs, promptConfigs);
      this.saveReport('validation', validationResults);

      if (validationResults.errors.length > 0) {
        errors.push(...validationResults.errors);
      }
      if (validationResults.warnings.length > 0) {
        warnings.push(...validationResults.warnings);
      }

      // Generate final report
      const duration = Date.now() - startTime;
      const summary = this.generateSummary({
        flowsMigrated: flowConfigs.length,
        promptsCreated: promptConfigs.length,
        uploadedFlows,
        uploadedPrompts,
        errors,
        warnings,
        duration,
      });

      console.log('\n' + summary);

      return {
        success: errors.length === 0,
        flowsMigrated: flowConfigs.length,
        promptsCreated: promptConfigs.length,
        errors,
        warnings,
        duration,
        summary,
      };
    } catch (error) {
      errors.push(`Migration failed: ${error}`);
      return {
        success: false,
        flowsMigrated: 0,
        promptsCreated: 0,
        errors,
        warnings,
        duration: Date.now() - startTime,
        summary: 'Migration failed with errors',
      };
    }
  }

  /**
   * Analyze flows
   */
  private async analyzeFlows(): Promise<any> {
    const analyzer = new FlowAnalyzer(this.flowsDir);
    return await analyzer.analyzeAllFlows();
  }

  /**
   * Extract prompts
   */
  private async extractPrompts(flows: any[]): Promise<any> {
    const extractor = new PromptExtractor();
    const filePaths = flows.map(f => f.filePath);
    return await extractor.extractFromMultipleFiles(filePaths);
  }

  /**
   * Generate configurations
   */
  private async generateConfigs(flows: any[], promptResults: any[]): Promise<{
    flowConfigs: FlowConfiguration[];
    promptConfigs: PromptConfiguration[];
  }> {
    const generator = new ConfigGenerator();
    const flowConfigs = generator.generateMultipleConfigs(flows, promptResults);

    // Extract all prompt configurations
    const promptConfigs = promptResults.flatMap(r => r.configurations);

    return { flowConfigs, promptConfigs };
  }

  /**
   * Upload prompts to Firestore
   */
  private async uploadPrompts(prompts: PromptConfiguration[]): Promise<number> {
    if (!this.db) return 0;

    let uploaded = 0;
    const promptsCollection = collection(this.db, 'prompts');

    for (const prompt of prompts) {
      try {
        const promptDoc = doc(promptsCollection, prompt.name);
        await setDoc(promptDoc, {
          ...prompt,
          createdAt: new Date(),
          updatedAt: new Date(),
        });
        uploaded++;
        console.log(`   ✓ Uploaded prompt: ${prompt.name}`);
      } catch (error) {
        console.error(`   ✗ Failed to upload prompt ${prompt.name}:`, error);
      }
    }

    return uploaded;
  }

  /**
   * Upload flows to Firestore
   */
  private async uploadFlows(flows: FlowConfiguration[]): Promise<number> {
    if (!this.db) return 0;

    let uploaded = 0;
    const flowsCollection = collection(this.db, 'flows');

    for (const flow of flows) {
      try {
        const flowDoc = doc(flowsCollection, flow.name);
        await setDoc(flowDoc, {
          ...flow,
          createdAt: new Date(),
          updatedAt: new Date(),
        });
        uploaded++;
        console.log(`   ✓ Uploaded flow: ${flow.name}`);
      } catch (error) {
        console.error(`   ✗ Failed to upload flow ${flow.name}:`, error);
      }
    }

    return uploaded;
  }

  /**
   * Validate migration
   */
  private async validateMigration(
    flows: FlowConfiguration[],
    prompts: PromptConfiguration[]
  ): Promise<{ errors: string[]; warnings: string[] }> {
    const errors: string[] = [];
    const warnings: string[] = [];

    // Validate each flow
    flows.forEach(flow => {
      // Check if all referenced prompts exist
      flow.steps.forEach(step => {
        if (step.type === 'GENERATE') {
          const config = step.config as any;
          const promptExists = prompts.some(p => p.name === config.promptName);
          if (!promptExists) {
            errors.push(`Flow ${flow.name} references non-existent prompt: ${config.promptName}`);
          }
        }
      });

      // Check if flow has at least one step
      if (flow.steps.length === 0) {
        warnings.push(`Flow ${flow.name} has no steps`);
      }

      // Check if input/output schemas are defined
      if (!flow.inputSchema) {
        warnings.push(`Flow ${flow.name} missing input schema`);
      }
      if (!flow.outputSchema) {
        warnings.push(`Flow ${flow.name} missing output schema`);
      }
    });

    // Validate each prompt
    prompts.forEach(prompt => {
      // Check if variables are defined
      if (prompt.variables.length === 0 && prompt.templateContent.includes('{{')) {
        warnings.push(`Prompt ${prompt.name} has template variables but no variable definitions`);
      }

      // Check if template content exists
      if (!prompt.templateContent || prompt.templateContent.trim().length === 0) {
        errors.push(`Prompt ${prompt.name} has empty template content`);
      }
    });

    console.log(`   ✓ Validated ${flows.length} flows`);
    console.log(`   ✓ Validated ${prompts.length} prompts`);

    if (errors.length > 0) {
      console.log(`   ⚠️  Found ${errors.length} errors`);
    }
    if (warnings.length > 0) {
      console.log(`   ⚠️  Found ${warnings.length} warnings`);
    }

    return { errors, warnings };
  }

  /**
   * Filter flows by migration phase
   */
  private filterFlowsByPhase(flows: any[], phase: 1 | 2 | 3 | 'all'): any[] {
    if (phase === 'all') return flows;
    return flows.filter(f => f.migrationPhase === phase);
  }

  /**
   * Count total prompts
   */
  private countPrompts(promptResults: any[]): number {
    return promptResults.reduce((sum, r) => sum + r.prompts.length, 0);
  }

  /**
   * Save report to file
   */
  private saveReport(name: string, data: any): void {
    const outputPath = join(this.outputDir, `${name}-report.json`);

    // Create output directory if it doesn't exist
    const fs = require('fs');
    if (!fs.existsSync(this.outputDir)) {
      fs.mkdirSync(this.outputDir, { recursive: true });
    }

    writeFileSync(outputPath, JSON.stringify(data, null, 2));
    console.log(`   📄 Report saved: ${outputPath}`);
  }

  /**
   * Load report from file
   */
  private loadReport(name: string): any {
    const filePath = join(this.outputDir, `${name}-report.json`);
    return JSON.parse(readFileSync(filePath, 'utf-8'));
  }

  /**
   * Generate summary report
   */
  private generateSummary(data: {
    flowsMigrated: number;
    promptsCreated: number;
    uploadedFlows: number;
    uploadedPrompts: number;
    errors: string[];
    warnings: string[];
    duration: number;
  }): string {
    const { flowsMigrated, promptsCreated, uploadedFlows, uploadedPrompts, errors, warnings, duration } = data;

    const durationMin = Math.floor(duration / 60000);
    const durationSec = Math.floor((duration % 60000) / 1000);

    let summary = `
╔══════════════════════════════════════════════════════════════════════╗
║                    MIGRATION SUMMARY                                 ║
╚══════════════════════════════════════════════════════════════════════╝

✨ Migration Completed Successfully!

📊 Statistics:
   Flows Migrated:        ${flowsMigrated}
   Prompts Created:       ${promptsCreated}
   Flows Uploaded:        ${uploadedFlows}
   Prompts Uploaded:      ${uploadedPrompts}
   Duration:              ${durationMin}m ${durationSec}s

`;

    if (errors.length > 0) {
      summary += `\n❌ Errors (${errors.length}):\n`;
      errors.forEach(err => summary += `   • ${err}\n`);
    }

    if (warnings.length > 0) {
      summary += `\n⚠️  Warnings (${warnings.length}):\n`;
      warnings.forEach(warn => summary += `   • ${warn}\n`);
    }

    if (errors.length === 0 && warnings.length === 0) {
      summary += `\n✅ No errors or warnings!\n`;
    }

    summary += `\n📁 Output Directory: ${this.outputDir}`;
    summary += `\n📄 Generated Files:`;
    summary += `\n   • analysis-report.json`;
    summary += `\n   • prompts-report.json`;
    summary += `\n   • flow-configs-report.json`;
    summary += `\n   • prompt-configs-report.json`;
    summary += `\n   • validation-report.json`;

    summary += `\n\n🎯 Next Steps:`;
    summary += `\n   1. Review validation report`;
    summary += `\n   2. Test migrated flows`;
    summary += `\n   3. Compare outputs with original`;
    summary += `\n   4. Deploy to staging`;
    summary += `\n   5. Monitor performance`;

    return summary;
  }
}

// CLI Usage
if (require.main === module) {
  const args = process.argv.slice(2);
  const options: MigrationOptions = {
    phase: 'all',
    dryRun: args.includes('--dry-run'),
    skipAnalysis: args.includes('--skip-analysis'),
    skipExtraction: args.includes('--skip-extraction'),
    skipUpload: args.includes('--skip-upload'),
  };

  // Parse phase argument
  const phaseArg = args.find(arg => arg.startsWith('--phase='));
  if (phaseArg) {
    const phase = phaseArg.split('=')[1];
    if (phase === '1' || phase === '2' || phase === '3') {
      options.phase = parseInt(phase) as 1 | 2 | 3;
    }
  }

  const migrator = new BatchMigrator(options);

  migrator.migrate(options).then(result => {
    if (result.success) {
      console.log('\n✨ Migration completed successfully!');
      process.exit(0);
    } else {
      console.error('\n❌ Migration completed with errors');
      process.exit(1);
    }
  }).catch(error => {
    console.error('\n❌ Migration failed:', error);
    process.exit(1);
  });
}

export default BatchMigrator;
"}

{"file_path": "scripts/migration/compare-outputs.ts", "initial_content": "/**
 * Output Comparison Tool
 * 
 * Compares outputs between original hardcoded flows and migrated dynamic flows.
 * Calculates similarity scores and identifies differences.
 */

import { readFileSync, writeFileSync } from 'fs';
import { diffLines, diffWords } from 'diff';

interface ComparisonInput {
  flowName: string;
  testCases: Array<{
    name: string;
    input: any;
  }>;
}

interface ComparisonResult {
  flowName: string;
  testCase: string;
  originalOutput: string;
  migratedOutput: string;
  similarity: number;
  differences: Array<{
    type: 'added' | 'removed' | 'modified';
    content: string;
    line?: number;
  }>;
  status: 'passed' | 'failed' | 'warning';
  notes: string[];
}

interface ComparisonReport {
  totalTests: number;
  passed: number;
  failed: number;
  warnings: number;
  averageSimilarity: number;
  results: ComparisonResult[];
  summary: string;
}

export class OutputComparator {
  private similarityThreshold = 0.85; // 85% similarity to pass
  private warningThreshold = 0.95; // <95% triggers warning

  /**
   * Compare outputs for a single test case
   */
  public compareOutputs(
    flowName: string,
    testCaseName: string,
    originalOutput: string,
    migratedOutput: string
  ): ComparisonResult {
    // Normalize outputs
    const normalizedOriginal = this.normalizeOutput(originalOutput);
    const normalizedMigrated = this.normalizeOutput(migratedOutput);

    // Calculate similarity
    const similarity = this.calculateSimilarity(normalizedOriginal, normalizedMigrated);

    // Find differences
    const differences = this.findDifferences(normalizedOriginal, normalizedMigrated);

    // Determine status
    const status = this.determineStatus(similarity, differences);

    // Generate notes
    const notes = this.generateNotes(similarity, differences);

    return {
      flowName,
      testCase: testCaseName,
      originalOutput,
      migratedOutput,
      similarity,
      differences,
      status,
      notes,
    };
  }

  /**
   * Normalize output for comparison
   */
  private normalizeOutput(output: string): string {
    return output
      .trim()
      .replace(/\s+/g, ' ') // Normalize whitespace
      .replace(/\n+/g, '\n') // Normalize line breaks
      .toLowerCase();
  }

  /**
   * Calculate similarity score using Levenshtein distance
   */
  private calculateSimilarity(str1: string, str2: string): number {
    const longer = str1.length > str2.length ? str1 : str2;
    const shorter = str1.length > str2.length ? str2 : str1;

    if (longer.length === 0) {
      return 1.0;
    }

    const distance = this.levenshteinDistance(longer, shorter);
    return (longer.length - distance) / longer.length;
  }

  /**
   * Calculate Levenshtein distance
   */
  private levenshteinDistance(str1: string, str2: string): number {
    const matrix: number[][] = [];

    for (let i = 0; i <= str2.length; i++) {
      matrix[i] = [i];
    }

    for (let j = 0; j <= str1.length; j++) {
      matrix[0][j] = j;
    }

    for (let i = 1; i <= str2.length; i++) {
      for (let j = 1; j <= str1.length; j++) {
        if (str2.charAt(i - 1) === str1.charAt(j - 1)) {
          matrix[i][j] = matrix[i - 1][j - 1];
        } else {
          matrix[i][j] = Math.min(
            matrix[i - 1][j - 1] + 1, // substitution
            matrix[i][j - 1] + 1,     // insertion
            matrix[i - 1][j] + 1      // deletion
          );
        }
      }
    }

    return matrix[str2.length][str1.length];
  }

  /**
   * Find specific differences between outputs
   */
  private findDifferences(
    original: string,
    migrated: string
  ): Array<{ type: 'added' | 'removed' | 'modified'; content: string; line?: number }> {
    const differences: Array<{ type: 'added' | 'removed' | 'modified'; content: string; line?: number }> = [];

    // Line-by-line comparison
    const diff = diffLines(original, migrated);
    let lineNumber = 0;

    diff.forEach(part => {
      if (part.added) {
        differences.push({
          type: 'added',
          content: part.value,
          line: lineNumber,
        });
      } else if (part.removed) {
        differences.push({
          type: 'removed',
          content: part.value,
          line: lineNumber,
        });
      } else {
        lineNumber += part.value.split('\n').length - 1;
      }
    });

    return differences;
  }

  /**
   * Determine test status
   */
  private determineStatus(
    similarity: number,
    differences: Array<any>
  ): 'passed' | 'failed' | 'warning' {
    if (similarity < this.similarityThreshold) {
      return 'failed';
    }

    if (similarity < this.warningThreshold) {
      return 'warning';
    }

    return 'passed';
  }

  /**
   * Generate notes about the comparison
   */
  private generateNotes(similarity: number, differences: Array<any>): string[] {
    const notes: string[] = [];

    notes.push(`Similarity score: ${(similarity * 100).toFixed(2)}%`);

    if (differences.length > 0) {
      const added = differences.filter(d => d.type === 'added').length;
      const removed = differences.filter(d => d.type === 'removed').length;

      if (added > 0) {
        notes.push(`${added} additions found`);
      }
      if (removed > 0) {
        notes.push(`${removed} removals found`);
      }
    }

    if (similarity < this.similarityThreshold) {
      notes.push('⚠️ Output differs significantly from original');
    } else if (similarity < this.warningThreshold) {
      notes.push('⚠️ Minor differences detected');
    } else {
      notes.push('✅ Output matches original closely');
    }

    return notes;
  }

  /**
   * Run comparison for multiple test cases
   */
  public async runComparison(
    flowName: string,
    originalExecutor: (input: any) => Promise<string>,
    migratedExecutor: (input: any) => Promise<string>,
    testCases: Array<{ name: string; input: any }>
  ): Promise<ComparisonResult[]> {
    const results: ComparisonResult[] = [];

    for (const testCase of testCases) {
      try {
        console.log(`   Testing: ${testCase.name}...`);

        const originalOutput = await originalExecutor(testCase.input);
        const migratedOutput = await migratedExecutor(testCase.input);

        const result = this.compareOutputs(
          flowName,
          testCase.name,
          originalOutput,
          migratedOutput
        );

        results.push(result);

        const statusIcon = {
          passed: '✅',
          warning: '⚠️',
          failed: '❌',
        }[result.status];

        console.log(`   ${statusIcon} ${testCase.name}: ${(result.similarity * 100).toFixed(2)}% similarity`);
      } catch (error) {
        console.error(`   ❌ Error testing ${testCase.name}:`, error);
      }
    }

    return results;
  }

  /**
   * Generate comparison report
   */
  public generateReport(results: ComparisonResult[]): ComparisonReport {
    const totalTests = results.length;
    const passed = results.filter(r => r.status === 'passed').length;
    const failed = results.filter(r => r.status === 'failed').length;
    const warnings = results.filter(r => r.status === 'warning').length;

    const averageSimilarity = results.reduce((sum, r) => sum + r.similarity, 0) / totalTests;

    const summary = this.generateSummary({
      totalTests,
      passed,
      failed,
      warnings,
      averageSimilarity,
    });

    return {
      totalTests,
      passed,
      failed,
      warnings,
      averageSimilarity,
      results,
      summary,
    };
  }

  /**
   * Generate summary text
   */
  private generateSummary(data: {
    totalTests: number;
    passed: number;
    failed: number;
    warnings: number;
    averageSimilarity: number;
  }): string {
    const { totalTests, passed, failed, warnings, averageSimilarity } = data;

    let summary = `
╔══════════════════════════════════════════════════════════════════════╗
║                    OUTPUT COMPARISON REPORT                          ║
╚══════════════════════════════════════════════════════════════════════╝

📊 Test Results:
   Total Tests:           ${totalTests}
   ✅ Passed:             ${passed} (${((passed / totalTests) * 100).toFixed(1)}%)
   ⚠️  Warnings:          ${warnings} (${((warnings / totalTests) * 100).toFixed(1)}%)
   ❌ Failed:             ${failed} (${((failed / totalTests) * 100).toFixed(1)}%)

   Average Similarity:    ${(averageSimilarity * 100).toFixed(2)}%
`;

    if (failed > 0) {
      summary += `\n⚠️  Some tests failed. Review differences carefully.`;
    } else if (warnings > 0) {
      summary += `\n⚠️  Some tests have minor differences. Consider reviewing.`;
    } else {
      summary += `\n✅ All tests passed! Migration successful.`;
    }

    return summary;
  }

  /**
   * Export report to JSON
   */
  public exportReport(report: ComparisonReport, outputPath: string): void {
    writeFileSync(outputPath, JSON.stringify(report, null, 2));
    console.log(`\n✅ Comparison report saved to ${outputPath}`);
  }

  /**
   * Print detailed results
   */
  public printDetailedResults(results: ComparisonResult[]): void {
    console.log('\n' + '='.repeat(70));
    console.log('DETAILED COMPARISON RESULTS');
    console.log('='.repeat(70) + '\n');

    results.forEach((result, index) => {
      const statusIcon = {
        passed: '✅',
