{"file_path": "scripts/migration/validate-migration.ts", "initial_content": "/**
 * Migration Validation Script
 * 
 * Validates migrated flows and prompts for correctness, completeness,
 * and compatibility with the dynamic flow system.
 */

import { FlowConfiguration } from '@/lib/models/flow-config';
import { PromptConfiguration } from '@/lib/models/prompt-config';
import { z } from 'zod';

interface ValidationError {
  severity: 'error' | 'warning' | 'info';
  category: string;
  message: string;
  location?: string;
  suggestion?: string;
}

interface ValidationResult {
  valid: boolean;
  errors: ValidationError[];
  warnings: ValidationError[];
  info: ValidationError[];
  score: number; // 0-100
}

export class MigrationValidator {
  /**
   * Validate flow configuration
   */
  public validateFlow(flow: FlowConfiguration): ValidationResult {
    const errors: ValidationError[] = [];
    const warnings: ValidationError[] = [];
    const info: ValidationError[] = [];

    // Required fields validation
    this.validateRequiredFields(flow, errors);

    // Schema validation
    this.validateSchemas(flow, errors, warnings);

    // Step validation
    this.validateSteps(flow, errors, warnings);

    // Naming conventions
    this.validateNamingConventions(flow, warnings);

    // Best practices
    this.validateBestPractices(flow, info);

    const score = this.calculateScore(errors, warnings);

    return {
      valid: errors.length === 0,
      errors,
      warnings,
      info,
      score,
    };
  }

  /**
   * Validate required fields
   */
  private validateRequiredFields(
    flow: FlowConfiguration,
    errors: ValidationError[]
  ): void {
    if (!flow.name || flow.name.trim().length === 0) {
      errors.push({
        severity: 'error',
        category: 'Required Field',
        message: 'Flow name is required',
        suggestion: 'Add a unique flow name using kebab-case',
      });
    }

    if (!flow.displayName || flow.displayName.trim().length === 0) {
      errors.push({
        severity: 'error',
        category: 'Required Field',
        message: 'Display name is required',
        suggestion: 'Add a human-readable display name',
      });
    }

    if (!flow.steps || flow.steps.length === 0) {
      errors.push({
        severity: 'error',
        category: 'Required Field',
        message: 'Flow must have at least one step',
        suggestion: 'Add steps to define the flow logic',
      });
    }
  }

  /**
   * Validate schemas
   */
  private validateSchemas(
    flow: FlowConfiguration,
    errors: ValidationError[],
    warnings: ValidationError[]
  ): void {
    if (!flow.inputSchema) {
      warnings.push({
        severity: 'warning',
        category: 'Schema',
        message: 'Input schema is missing',
        suggestion: 'Define input schema for type safety',
      });
    } else {
      this.validateJSONSchema(flow.inputSchema, 'input', errors);
    }

    if (!flow.outputSchema) {
      warnings.push({
        severity: 'warning',
        category: 'Schema',
        message: 'Output schema is missing',
        suggestion: 'Define output schema for type safety',
      });
    } else {
      this.validateJSONSchema(flow.outputSchema, 'output', errors);
    }
  }

  /**
   * Validate JSON schema
   */
  private validateJSONSchema(
    schema: any,
    type: string,
    errors: ValidationError[]
  ): void {
    if (!schema.type) {
      errors.push({
        severity: 'error',
        category: 'Schema',
        message: `${type} schema missing 'type' property`,
        location: `${type}Schema`,
      });
    }

    if (schema.type === 'object' && !schema.properties) {
      errors.push({
        severity: 'error',
        category: 'Schema',
        message: `${type} schema missing 'properties'`,
        location: `${type}Schema`,
      });
    }
  }

  /**
   * Validate steps
   */
  private validateSteps(
    flow: FlowConfiguration,
    errors: ValidationError[],
    warnings: ValidationError[]
  ): void {
    flow.steps.forEach((step, index) => {
      // Validate step ID
      if (!step.id) {
        errors.push({
          severity: 'error',
          category: 'Step',
          message: `Step ${index + 1} missing ID`,
          location: `steps[${index}]`,
        });
      }

      // Validate step type
      const validTypes = ['GENERATE', 'RETRIEVE', 'TOOL', 'FORMAT', 'CONDITION', 'LOOP'];
      if (!validTypes.includes(step.type)) {
        errors.push({
          severity: 'error',
          category: 'Step',
          message: `Invalid step type: ${step.type}`,
          location: `steps[${index}]`,
          suggestion: `Use one of: ${validTypes.join(', ')}`,
        });
      }

      // Validate step config
      this.validateStepConfig(step, index, errors, warnings);

      // Validate step schemas
      if (!step.inputSchema) {
        warnings.push({
          severity: 'warning',
          category: 'Step',
          message: `Step ${index + 1} (${step.name}) missing input schema`,
          location: `steps[${index}]`,
        });
      }

      if (!step.outputSchema) {
        warnings.push({
          severity: 'warning',
          category: 'Step',
          message: `Step ${index + 1} (${step.name}) missing output schema`,
          location: `steps[${index}]`,
        });
      }
    });

    // Check for duplicate step IDs
    const stepIds = flow.steps.map(s => s.id);
    const duplicates = stepIds.filter((id, index) => stepIds.indexOf(id) !== index);
    if (duplicates.length > 0) {
      errors.push({
        severity: 'error',
        category: 'Step',
        message: `Duplicate step IDs found: ${duplicates.join(', ')}`,
        suggestion: 'Ensure all step IDs are unique',
      });
    }
  }

  /**
   * Validate step configuration
   */
  private validateStepConfig(
    step: any,
    index: number,
    errors: ValidationError[],
    warnings: ValidationError[]
  ): void {
    if (!step.config) {
      errors.push({
        severity: 'error',
        category: 'Step Config',
        message: `Step ${index + 1} missing config`,
        location: `steps[${index}].config`,
      });
      return;
    }

    switch (step.type) {
      case 'GENERATE':
        if (!step.config.promptName) {
          errors.push({
            severity: 'error',
            category: 'Step Config',
            message: `GENERATE step ${index + 1} missing promptName`,
            location: `steps[${index}].config`,
          });
        }
        break;

      case 'RETRIEVE':
        if (!step.config.query) {
          errors.push({
            severity: 'error',
            category: 'Step Config',
            message: `RETRIEVE step ${index + 1} missing query`,
            location: `steps[${index}].config`,
          });
        }
        if (!step.config.collection) {
          warnings.push({
            severity: 'warning',
            category: 'Step Config',
            message: `RETRIEVE step ${index + 1} missing collection name`,
            location: `steps[${index}].config`,
          });
        }
        break;

      case 'TOOL':
        if (!step.config.toolName) {
          errors.push({
            severity: 'error',
            category: 'Step Config',
            message: `TOOL step ${index + 1} missing toolName`,
            location: `steps[${index}].config`,
          });
        }
        break;

      case 'FORMAT':
        if (!step.config.format) {
          warnings.push({
            severity: 'warning',
            category: 'Step Config',
            message: `FORMAT step ${index + 1} missing format type`,
            location: `steps[${index}].config`,
          });
        }
        break;

      case 'CONDITION':
        if (!step.config.expression) {
          errors.push({
            severity: 'error',
            category: 'Step Config',
            message: `CONDITION step ${index + 1} missing expression`,
            location: `steps[${index}].config`,
          });
        }
        break;

      case 'LOOP':
        if (!step.config.items) {
          errors.push({
            severity: 'error',
            category: 'Step Config',
            message: `LOOP step ${index + 1} missing items`,
            location: `steps[${index}].config`,
          });
        }
        break;
    }
  }

  /**
   * Validate naming conventions
   */
  private validateNamingConventions(
    flow: FlowConfiguration,
    warnings: ValidationError[]
  ): void {
    // Flow name should be kebab-case
    if (!/^[a-z0-9]+(-[a-z0-9]+)*$/.test(flow.name)) {
      warnings.push({
        severity: 'warning',
        category: 'Naming',
        message: 'Flow name should use kebab-case',
        location: 'name',
        suggestion: 'Use lowercase letters, numbers, and hyphens only',
      });
    }

    // Check for reserved names
    const reservedNames = ['test', 'debug', 'admin', 'system'];
    if (reservedNames.some(reserved => flow.name.includes(reserved))) {
      warnings.push({
        severity: 'warning',
        category: 'Naming',
        message: 'Flow name contains reserved word',
        location: 'name',
      });
    }
  }

  /**
   * Validate best practices
   */
  private validateBestPractices(
    flow: FlowConfiguration,
    info: ValidationError[]
  ): void {
    // Description should be meaningful
    if (flow.description && flow.description.length < 20) {
      info.push({
        severity: 'info',
        category: 'Best Practice',
        message: 'Consider adding a more detailed description',
        location: 'description',
      });
    }

    // Tags help with organization
    if (!flow.tags || flow.tags.length === 0) {
      info.push({
        severity: 'info',
        category: 'Best Practice',
        message: 'Consider adding tags for better organization',
        location: 'tags',
      });
    }

    // Too many steps might indicate complexity
    if (flow.steps && flow.steps.length > 10) {
      info.push({
        severity: 'info',
        category: 'Best Practice',
        message: 'Flow has many steps, consider breaking into smaller flows',
        location: 'steps',
      });
    }

    // Version should follow semver
    if (flow.version && !/^\d+\.\d+\.\d+$/.test(flow.version)) {
      info.push({
        severity: 'info',
        category: 'Best Practice',
        message: 'Version should follow semantic versioning (x.y.z)',
        location: 'version',
      });
    }
  }

  /**
   * Validate prompt configuration
   */
  public validatePrompt(prompt: PromptConfiguration): ValidationResult {
    const errors: ValidationError[] = [];
    const warnings: ValidationError[] = [];
    const info: ValidationError[] = [];

    // Required fields
    if (!prompt.name || prompt.name.trim().length === 0) {
      errors.push({
        severity: 'error',
        category: 'Required Field',
        message: 'Prompt name is required',
      });
    }

    if (!prompt.templateContent || prompt.templateContent.trim().length === 0) {
      errors.push({
        severity: 'error',
        category: 'Required Field',
        message: 'Template content is required',
      });
    }

    // Validate variables
    if (prompt.templateContent) {
      this.validatePromptVariables(prompt, errors, warnings);
    }

    // Naming conventions
    if (prompt.name && !/^[a-z0-9]+(-[a-z0-9]+)*$/.test(prompt.name)) {
      warnings.push({
        severity: 'warning',
        category: 'Naming',
        message: 'Prompt name should use kebab-case',
      });
    }

    const score = this.calculateScore(errors, warnings);

    return {
      valid: errors.length === 0,
      errors,
      warnings,
      info,
      score,
    };
  }

  /**
   * Validate prompt variables
   */
  private validatePromptVariables(
    prompt: PromptConfiguration,
    errors: ValidationError[],
    warnings: ValidationError[]
  ): void {
    // Extract variables from template
    const templateVars = new Set<string>();
    const regex = /\{\{([^}]+)\}\}/g;
    let match;

    while ((match = regex.exec(prompt.templateContent)) !== null) {
      const varName = match[1].trim().split('.')[0];
      templateVars.add(varName);
    }

    // Check if all template variables are defined
    const definedVars = new Set(prompt.variables.map(v => v.name));

    templateVars.forEach(varName => {
      if (!definedVars.has(varName)) {
        warnings.push({
          severity: 'warning',
          category: 'Variables',
          message: `Template uses undefined variable: {{${varName}}}`,
          suggestion: 'Add variable definition or remove from template',
        });
      }
    });

    // Check for unused variables
    definedVars.forEach(varName => {
      if (!templateVars.has(varName)) {
        info.push({
          severity: 'info',
          category: 'Variables',
          message: `Variable '${varName}' is defined but not used`,
        });
      }
    });
  }

  /**
   * Calculate validation score
   */
  private calculateScore(errors: ValidationError[], warnings: ValidationError[]): number {
    let score = 100;
    score -= errors.length * 20; // Each error reduces score by 20
    score -= warnings.length * 5; // Each warning reduces score by 5
    return Math.max(0, Math.min(100, score));
  }

  /**
   * Validate multiple flows
   */
  public validateFlows(flows: FlowConfiguration[]): {
    results: Map<string, ValidationResult>;
    summary: {
      total: number;
      valid: number;
      invalid: number;
      averageScore: number;
    };
  } {
    const results = new Map<string, ValidationResult>();

    flows.forEach(flow => {
      const result = this.validateFlow(flow);
      results.set(flow.name, result);
    });

    const validCount = Array.from(results.values()).filter(r => r.valid).length;
    const averageScore =
      Array.from(results.values()).reduce((sum, r) => sum + r.score, 0) / flows.length;

    return {
      results,
      summary: {
        total: flows.length,
        valid: validCount,
        invalid: flows.length - validCount,
        averageScore,
      },
    };
  }

  /**
   * Print validation results
   */
  public printResults(flowName: string, result: ValidationResult): void {
    console.log(`\n${'='.repeat(70)}`);
    console.log(`Validation: ${flowName}`);
    console.log(`Score: ${result.score}/100 ${this.getScoreEmoji(result.score)}`);
    console.log(`Status: ${result.valid ? '✅ Valid' : '❌ Invalid'}`);
    console.log('='.repeat(70));

    if (result.errors.length > 0) {
      console.log('\n❌ Errors:');
      result.errors.forEach(err => {
        console.log(`   • [${err.category}] ${err.message}`);
        if (err.location) console.log(`     Location: ${err.location}`);
        if (err.suggestion) console.log(`     💡 ${err.suggestion}`);
      });
    }

    if (result.warnings.length > 0) {
      console.log('\n⚠️  Warnings:');
      result.warnings.forEach(warn => {
        console.log(`   • [${warn.category}] ${warn.message}`);
        if (warn.suggestion) console.log(`     💡 ${warn.suggestion}`);
      });
    }

    if (result.info.length > 0) {
      console.log('\nℹ️  Info:');
      result.info.forEach(info => {
        console.log(`   • [${info.category}] ${info.message}`);
      });
    }

    if (result.valid && result.errors.length === 0 && result.warnings.length === 0) {
      console.log('\n✅ All checks passed!');
    }
  }

  /**
   * Get score emoji
   */
  private getScoreEmoji(score: number): string {
    if (score >= 90) return '🌟';
    if (score >= 75) return '✅';
    if (score >= 60) return '⚠️';
    return '❌';
  }
}

// CLI Usage
if (require.main === module) {
  console.log('Migration Validation Tool');
  console.log('Usage: ts-node validate-migration.ts');
  console.log('\nValidates flow and prompt configurations for correctness.');
}

export default MigrationValidator;
"}

{"file_path": "src/components/admin/prompts/PromptTester.tsx", "initial_content": "/**
 * Prompt Tester Component
 * 
 * Interactive testing interface for prompt templates with variable substitution.
 */

'use client';

import React, { useState } from 'react';
import { PromptConfiguration, PromptVariable } from '@/lib/models/prompt-config';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { Separator } from '@/components/ui/separator';
import { Play, Copy, Download, CheckCircle, XCircle, Loader2, RefreshCw } from 'lucide-react';
import { cn } from '@/lib/utils/cn';

interface PromptTesterProps {
  prompt: PromptConfiguration;
  onTest?: (variables: Record<string, any>) => Promise<{
    success: boolean;
    output?: string;
    error?: string;
    metadata?: any;
  }>;
}

interface TestResult {
  timestamp: Date;
  variables: Record<string, any>;
  renderedPrompt: string;
  output?: string;
  error?: string;
  duration?: number;
  metadata?: any;
}

export function PromptTester({ prompt, onTest }: PromptTesterProps) {
  const [variables, setVariables] = useState<Record<string, any>>({});
  const [testResult, setTestResult] = useState<TestResult | null>(null);
  const [isRunning, setIsRunning] = useState(false);
  const [activeTab, setActiveTab] = useState('variables');
  const [testHistory, setTestHistory] = useState<TestResult[]>([]);

  // Initialize variables with default values
  React.useEffect(() => {
    const initialVars: Record<string, any> = {};
    prompt.variables.forEach(v => {
      if (v.defaultValue !== undefined) {
        initialVars[v.name] = v.defaultValue;
      } else {
        // Set default based on type
        switch (v.type) {
          case 'string':
            initialVars[v.name] = '';
            break;
          case 'number':
            initialVars[v.name] = 0;
            break;
          case 'boolean':
            initialVars[v.name] = false;
            break;
          case 'array':
            initialVars[v.name] = [];
            break;
          case 'object':
            initialVars[v.name] = {};
            break;
        }
      }
    });
    setVariables(initialVars);
  }, [prompt.variables]);

  /**
   * Render prompt with variables
   */
  const renderPrompt = (vars: Record<string, any>): string => {
    let rendered = prompt.templateContent;

    // Replace {{variable}} syntax
    Object.entries(vars).forEach(([key, value]) => {
      const regex = new RegExp(`\\{\\{${key}\\}\\}`, 'g');
      rendered = rendered.replace(regex, String(value));
    });

    return rendered;
  };

  /**
   * Handle variable change
   */
  const handleVariableChange = (name: string, value: any) => {
    setVariables({ ...variables, [name]: value });
  };

  /**
   * Validate variables
   */
  const validateVariables = (): { valid: boolean; errors: string[] } => {
    const errors: string[] = [];

    prompt.variables.forEach(v => {
      if (v.required && (variables[v.name] === undefined || variables[v.name] === '')) {
        errors.push(`${v.name} is required`);
      }

      // Type validation
      const value = variables[v.name];
      if (value !== undefined && value !== '') {
        switch (v.type) {
          case 'number':
            if (isNaN(Number(value))) {
              errors.push(`${v.name} must be a number`);
            }
            break;
          case 'boolean':
            if (typeof value !== 'boolean') {
              errors.push(`${v.name} must be a boolean`);
            }
            break;
          case 'array':
            if (!Array.isArray(value)) {
              errors.push(`${v.name} must be an array`);
            }
            break;
          case 'object':
            if (typeof value !== 'object' || Array.isArray(value)) {
              errors.push(`${v.name} must be an object`);
            }
            break;
        }
      }
    });

    return { valid: errors.length === 0, errors };
  };

  /**
   * Run test
   */
  const handleTest = async () => {
    // Validate variables
    const validation = validateVariables();
    if (!validation.valid) {
      setTestResult({
        timestamp: new Date(),
        variables,
        renderedPrompt: renderPrompt(variables),
        error: validation.errors.join(', '),
      });
      setActiveTab('result');
      return;
    }

    setIsRunning(true);
    const startTime = Date.now();

    try {
      const renderedPrompt = renderPrompt(variables);

      if (onTest) {
        // Call actual test API
        const result = await onTest(variables);
        const duration = Date.now() - startTime;

        const testResult: TestResult = {
          timestamp: new Date(),
          variables,
          renderedPrompt,
          output: result.output,
          error: result.error,
          duration,
          metadata: result.metadata,
        };

        setTestResult(testResult);
        setTestHistory([testResult, ...testHistory.slice(0, 9)]); // Keep last 10
        setActiveTab('result');
      } else {
        // Mock test (just show rendered prompt)
        setTestResult({
          timestamp: new Date(),
          variables,
          renderedPrompt,
          output: 'Mock output - Connect to API for actual testing',
          duration: Date.now() - startTime,
        });
        setActiveTab('result');
      }
    } catch (error) {
      setTestResult({
        timestamp: new Date(),
        variables,
        renderedPrompt: renderPrompt(variables),
        error: error instanceof Error ? error.message : 'Unknown error',
      });
      setActiveTab('result');
    } finally {
      setIsRunning(false);
    }
  };

  /**
   * Copy to clipboard
   */
  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
  };

  /**
   * Load test case from history
   */
  const loadHistoryItem = (item: TestResult) => {
    setVariables(item.variables);
    setTestResult(item);
  };

  /**
   * Render variable input
   */
  const renderVariableInput = (variable: PromptVariable) => {
    const value = variables[variable.name];

    switch (variable.type) {
      case 'boolean':
        return (
          <div className="flex items-center space-x-2">
            <input
              type="checkbox"
              checked={value || false}
              onChange={(e) => handleVariableChange(variable.name, e.target.checked)}
              className="rounded"
            />
          </div>
        );

      case 'number':
        return (
          <Input
            type="number"
            value={value || ''}
            onChange={(e) => handleVariableChange(variable.name, parseFloat(e.target.value))}
            placeholder={`Enter ${variable.name}`}
          />
        );

      case 'array':
      case 'object':
        return (
          <Textarea
            value={typeof value === 'string' ? value : JSON.stringify(value, null, 2)}
            onChange={(e) => {
              try {
                const parsed = JSON.parse(e.target.value);
                handleVariableChange(variable.name, parsed);
              } catch {
                // Invalid JSON, keep as string
                handleVariableChange(variable.name, e.target.value);
              }
            }}
            placeholder={`Enter ${variable.type} as JSON`}
            rows={4}
            className="font-mono text-xs"
          />
        );

      default:
        return (
          <Textarea
            value={value || ''}
            onChange={(e) => handleVariableChange(variable.name, e.target.value)}
            placeholder={`Enter ${variable.name}`}
            rows={3}
          />
        );
    }
  };

  return (
    <div className="h-full flex flex-col">
      {/* Header */}
      <div className="p-4 border-b">
        <div className="flex items-center justify-between">
          <div>
            <h3 className="font-semibold">Test Prompt</h3>
            <p className="text-sm text-muted-foreground">{prompt.displayName}</p>
          </div>
          <Button onClick={handleTest} disabled={isRunning}>
            {isRunning ? (
              <Loader2 className="w-4 h-4 mr-2 animate-spin" />
            ) : (
              <Play className="w-4 h-4 mr-2" />
            )}
            Run Test
          </Button>
        </div>
      </div>

      {/* Content */}
      <div className="flex-1 overflow-hidden">
        <Tabs value={activeTab} onValueChange={setActiveTab} className="h-full flex flex-col">
          <TabsList className="mx-4 mt-4">
            <TabsTrigger value="variables">Variables</TabsTrigger>
            <TabsTrigger value="preview">Preview</TabsTrigger>
            <TabsTrigger value="result">Result</TabsTrigger>
            <TabsTrigger value="history">History</TabsTrigger>
          </TabsList>

          {/* Variables Tab */}
          <TabsContent value="variables" className="flex-1 px-4 pb-4 overflow-auto">
            <Card>
              <CardHeader>
                <CardTitle className="text-base">Input Variables</CardTitle>
                <CardDescription>
                  Provide values for all variables used in the prompt
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-4">
                {prompt.variables.map((variable) => (
                  <div key={variable.name} className="space-y-2">
                    <div className="flex items-center justify-between">
                      <Label htmlFor={variable.name}>
                        {variable.name}
                        {variable.required && <span className="text-destructive ml-1">*</span>}
                      </Label>
                      <Badge variant="outline" className="text-xs">
                        {variable.type}
                      </Badge>
                    </div>
                    {variable.description && (
                      <p className="text-xs text-muted-foreground">{variable.description}</p>
                    )}
                    {renderVariableInput(variable)}
                  </div>
                ))}

                {prompt.variables.length === 0 && (
                  <p className="text-sm text-muted-foreground text-center py-4">
                    No variables defined for this prompt
                  </p>
                )}
              </CardContent>
            </Card>
          </TabsContent>

          {/* Preview Tab */}
          <TabsContent value="preview" className="flex-1 px-4 pb-4 overflow-auto">
            <Card>
              <CardHeader>
                <div className="flex items-center justify-between">
                  <CardTitle className="text-base">Rendered Prompt</CardTitle>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => copyToClipboard(renderPrompt(variables))}
                  >
                    <Copy className="w-4 h-4 mr-2" />
                    Copy
                  </Button>
                </div>
                <CardDescription>
                  Preview with current variable values
                </CardDescription>
              </CardHeader>
              <CardContent>
                <div className="p-4 bg-muted rounded-lg">
                  <pre className="text-sm whitespace-pre-wrap font-mono">
                    {renderPrompt(variables)}
                  </pre>
                </div>
              </CardContent>
            </Card>
          </TabsContent>

          {/* Result Tab */}
          <TabsContent value="result" className="flex-1 px-4 pb-4 overflow-auto">
            <Card>
              <CardHeader>
                <div className="flex items-center justify-between">
                  <CardTitle className="text-base">Test Result</CardTitle>
                  {testResult && (
                    <div className="flex items-center gap-2">
                      {testResult.error ? (
                        <Badge variant="destructive">
                          <XCircle className="w-3 h-3 mr-1" />
                          Failed
                        </Badge>
                      ) : (
                        <Badge variant="default" className="bg-green-500">
                          <CheckCircle className="w-3 h-3 mr-1" />
                          Success
                        </Badge>
                      )}
                      {testResult.duration && (
                        <Badge variant="outline">{testResult.duration}ms</Badge>
                      )}
                    </div>
                  )}
                </div>
              </CardHeader>
              <CardContent>
                {!testResult ? (
                  <div className="text-center py-8 text-muted-foreground">
                    <Play className="w-12 h-12 mx-auto mb-4 opacity-50" />
                    <p>Run a test to see results</p>
                  </div>
                ) : (
                  <div className="space-y-4">
                    {testResult.error ? (
                      <Alert variant="destructive">
                        <XCircle className="w-4 h-4" />
                        <AlertDescription>{testResult.error}</AlertDescription>
                      </Alert>
                    ) : (
                      <>
                        <div>
                          <Label className="text-xs text-muted-foreground">Output</Label>
                          <div className="mt-2 p-4 bg-muted rounded-lg">
                            <pre className="text-sm whitespace-pre-wrap">
                              {testResult.output || 'No output'}
                            </pre>
                          </div>
                        </div>

                        {testResult.metadata && (
                          <div>
                            <Label className="text-xs text-muted-foreground">Metadata</Label>
                            <div className="mt-2 p-4 bg-muted rounded-lg">
                              <pre className="text-xs font-mono">
                                {JSON.stringify(testResult.metadata, null, 2)}
                              </pre>
                            </div>
                          </div>
                        )}
                      </>
                    )}

                    <Separator />

                    <div>
                      <Label className="text-xs text-muted-foreground">Rendered Prompt</Label>
                      <div className="mt-2 p-4 bg-muted rounded-lg">
                        <pre className="text-sm whitespace-pre-wrap font-mono">
                          {testResult.renderedPrompt}
                        </pre>
                      </div>
                    </div>
                  </div>
                )}
              </CardContent>
            </Card>
          </TabsContent>

          {/* History Tab */}
          <TabsContent value="history" className="flex-1 px-4 pb-4 overflow-auto">
            <Card>
              <CardHeader>
                <CardTitle className="text-base">Test History</CardTitle>
                <CardDescription>Recent test executions</CardDescription>
              </CardHeader>
              <CardContent>
                {testHistory.length === 0 ? (
                  <p className="text-sm text-muted-foreground text-center py-8">
                    No test history yet
                  </p>
                ) : (
                  <div className="space-y-2">
                    {testHistory.map((item, index) => (
                      <Card
                        key={index}
                        className="cursor-pointer hover:border-primary transition-colors"
                        onClick={() => loadHistoryItem(item)}
                      >
                        <CardContent className="p-4">
                          <div className="flex items-start justify-between">
                            <div className="flex-1">
                              <div className="flex items-center gap-2 mb-2">
                                {item.error ? (
                                  <XCircle className="w-4 h-4 text-destructive" />
                                ) : (
                                  <CheckCircle className="w-4 h-4 text-green-500" />
                                )}
                                <span className="text-xs text-muted-foreground">
                                  {item.timestamp.toLocaleString()}
                                </span>
                                {item.duration && (
                                  <Badge variant="outline" className="text-xs">
                                    {item.duration}ms
                                  </Badge>
                                )}
                              </div>
                              <p className="text-xs text-muted-foreground line-clamp-2">
                                {Object.entries(item.variables)
                                  .map(([k, v]) => `${k}: ${JSON.stringify(v)}`)
                                  .join(', ')}
                              </p>
                            </div>
                            <Button variant="ghost" size="sm" className="h-6 px-2">
                              <RefreshCw className="w-3 h-3" />
                            </Button>
                          </div>
                        </CardContent>
                      </Card>
                    ))}
                  </div>
                )}
              </CardContent>
            </Card>
          </TabsContent>
        </Tabs>
      </div>
    </div>
  );
}

export default PromptTester;
"}

